import type { MeaningPack } from '../../types';

export const taKirtana: MeaningPack = {
  lang: 'ta',
  texts: {
    'tiruppavai': {
      summary: 'மார்கழி நோன்பிற்காக ஆண்டாள் அருளிய முப்பது பாடல்கள். ஆய்ப்பாடிப் பெண்கள் விடியலுக்கு முன்பே ஒருவரையொருவர் எழுப்பி, நந்தகோபன் மாளிகைக்குச் சென்று கண்ணனையும் நப்பின்னையையும் எழுப்பி, அவனுக்குச் செய்யும் தொண்டாகிய “பறை”யை வேண்டுகிறார்கள். மார்கழியின் ஒவ்வொரு நாளும் ஒரு பாசுரம் பாடப்படுகிறது; முப்பதாவது பாசுரம் ஆசிரியரின் பெயரையும் பாடுவதன் பயனையும் கூறுகிறது.',
      verses: {
        '0.0': 'அன்னப் பறவைகள் நிறைந்த வயல்களையுடைய ஸ்ரீவில்லிபுத்தூரில் அவதரித்த ஆண்டாளின் திருநாமத்தைச் சொல்லுங்கள். அவள் அரங்கனுக்காகத் திருப்பாவைப் பாடல்களை இனிய இசையுடன் பாடி, பாமாலையையும் தான் சூடிய பூமாலையையும் அவனுக்கு அளித்தாள்.',
        '0.1': 'தான் சூடிய மாலையை அளித்த ஒளிமிக்க கொடியே, பழமையான பாவைப் பாட்டைப் பாடவல்ல வளையல் அணிந்தவளே, “என்னை வேங்கடவனுக்கு விதித்தருள்” என்று நீ சொன்ன வாக்கை நாங்கள் மீறாதபடி அருள்வாய்.',
        '1.0': 'மார்கழி மாதத்தின் முழுநிலவு நாளான இந்த நல்ல நாளில் நீராட வாருங்கள், அணிகலன்கள் பூண்ட பெண்களே, செழிப்பான ஆய்ப்பாடியின் செல்வச் சிறுமிகளே. கூரிய வேலும் கொடிய தொழிலும் உடைய நந்தகோபனின் மகனும், அழகிய கண்களையுடைய யசோதையின் இளஞ்சிங்கமும், கார்மேகம் போன்ற உடலும் செந்தாமரைக் கண்களும் சூரிய சந்திரர் போன்ற முகமும் உடையவனுமான நாராயணனே நமக்குப் பறை தருவான். உலகோர் புகழும்படி நோன்பில் சேருங்கள்.',
        '1.1': 'இவ்வுலகில் வாழ்பவர்களே, நம் நோன்புக்கு நாம் செய்யும் நெறிகளைக் கேளுங்கள். பாற்கடலில் மெல்லத் துயில்கொண்ட பரமனின் திருவடிகளைப் பாடுவோம். நெய் உண்ணமாட்டோம், பால் உண்ணமாட்டோம்; விடியற்காலையில் நீராடுவோம்; கண்ணுக்கு மை எழுதமாட்டோம், மலர் சூடமாட்டோம்; செய்யத்தகாதவற்றைச் செய்யமாட்டோம், தீய கோள் சொல்லமாட்டோம்; இயன்றவரை பிச்சையும் தானமும் அளித்து, உய்யும் வழியையே எண்ணி மகிழ்வோம்.',
        '1.2': 'ஓங்கி உலகளந்த உத்தமனின் திருநாமத்தைப் பாடி, நம் நோன்புக்குச் சமர்ப்பித்து நீராடினால், தீங்கின்றி நாடெல்லாம் மாதம் மூன்று முறை மழை பெய்யும்; உயர்ந்த செந்நெல் வயல்களுக்கிடையே கயல் மீன்கள் துள்ளும்; குவளை மலரில் வண்டுகள் உறங்கும்; வள்ளல் தன்மையுடைய பெரிய பசுக்கள் அசையாமல் நின்று, நிறைந்த மடியைப் பிடித்தவுடன் குடங்களை நிரப்பும்; நீங்காத செல்வம் நிறையும்.',
        '1.3': 'கடல்போல் ஆழமான மழைத் தலைவனே, ஒன்றையும் மறைக்காதே. கடலுக்குள் புகுந்து நீரை முகந்து முழங்கி எழுந்து, ஊழிமுதல்வனின் உருவம்போல் உடல் கறுத்து, வலிமையான தோள்களையுடைய பத்மநாபனின் கையிலுள்ள சக்கரம்போல் மின்னி, வலம்புரிச் சங்குபோல் இடித்து, தாமதமின்றி அவனது சார்ங்க வில்லின் அம்புமழைபோல் உலகம் வாழும்படி பொழிவாய்; நாங்களும் மார்கழியில் மகிழ்ந்து நீராடுவோம்.',
        '1.4': 'தூய்மையாக வந்து தூய மலர்களைத் தூவித் தொழுவோம்: நிலைத்த வடமதுரையின் மைந்தனும், தூய்மையான பெருநீர் யமுனையின் துறைவனும், ஆயர் குலத்தில் தோன்றிய அணிவிளக்கும், தாயின் வயிற்றை ஒளிரச் செய்த தாமோதரனுமான மாயனை. வாயால் பாடி மனத்தால் சிந்தித்தால், முன் செய்த பிழைகளும் இனி வரவிருப்பனவும் நெருப்பில் இட்ட தூசுபோல் அழியும். அவன் திருநாமத்தைச் சொல்லுங்கள்.',
        '2.0': 'பறவைகளும் கூவிவிட்டன; கருடனுக்குத் தலைவனின் கோயிலில் வெண்சங்கின் பேரொலி உன் காதில் விழவில்லையா? பெண்ணே, எழுந்திரு! பேய்ச்சியின் முலைநஞ்சை உண்டு, வஞ்சகச் சகடத்தை உதைத்து உடைத்து, வெள்ளத்தில் பாம்பணையில் துயின்ற மூலவித்தை உள்ளத்தில் கொண்டு, முனிவர்களும் யோகிகளும் மெல்ல எழுந்து “ஹரி” என்று முழங்கும் பேரொலி எங்கள் உள்ளத்தில் புகுந்து குளிர்விக்கிறது.',
        '2.1': 'ஆனைச்சாத்தன் பறவைகள் எங்கும் “கீச்சுக்கீச்சு” என்று கலந்து பேசும் ஆரவாரம் உன் காதில் விழவில்லையா, பேய்ப்பெண்ணே? மணம் வீசும் கூந்தலையுடைய ஆய்ச்சியர் கைகளை அசைத்து அணிந்த காசுமாலைகளும் அச்சுத்தாலியும் கலகலக்க மத்தால் தயிர் கடையும் ஒலி உனக்குக் கேட்கவில்லையா? தலைவியே, நாராயணமூர்த்தியான கேசவனை நாங்கள் பாடுவதைக் கேட்டும் படுத்திருக்கிறாயா? ஒளியுடையவளே, கதவைத் திற.',
        '2.2': 'கீழ்வானம் வெளுத்துவிட்டது; எருமைகள் சிறுவீடு மேய்வதற்குப் பரவிவிட்டன; போகத் தொடங்கிய மற்ற பிள்ளைகளையும் போகாமல் நிறுத்தி உன்னை அழைக்க வந்து நிற்கிறோம். கொண்டாட்டம் மிக்க பெண்ணே, எழுந்திரு; பாடிப் பறைகொள்வோம். குதிரை வடிவ அசுரனின் வாயைப் பிளந்தவனும் மல்லர்களை அழித்தவனுமான தேவாதிதேவனைச் சென்று சேவித்தால், அவன் “ஆஆ” என்று நம் தேவையை ஆராய்ந்து அருள்வான்.',
        '2.3': 'தூய மணிகள் இழைத்த மாளிகையில் சுற்றிலும் விளக்கெரிய, தூபம் கமழ, மெத்தையில் துயிலும் மாமன் மகளே, மணிக்கதவின் தாளைத் திறவாய். மாமியே, அவளை எழுப்பமாட்டீரோ? உன் மகள் ஊமையோ, செவிடோ, சோம்பலோ? காவலுடன் பெருந்துயிலில் ஆழ்த்தப்பட்டாளோ, மந்திரத்தால் கட்டுண்டாளோ? “மாமாயன், மாதவன், வைகுந்தன்” என்று அவன் பல திருநாமங்களைச் சொல்வோம்.',
        '2.4': 'நோன்பிருந்து சொர்க்கம் புகும் அம்மையே! வாசல் திறவாதவர்கள் ஒரு மறுமொழியும் தரமாட்டார்களா? மணம் மிக்க துழாய் முடியணிந்த நாராயணன், நாம் போற்றினால் பறைதரும் புண்ணியன். முன்னொரு நாள் எமனின் வாயில் வீழ்ந்த கும்பகர்ணனும் தோற்று, தன் பெருந்தூக்கத்தை உனக்கே தந்தானோ? மிகுந்த தூக்கமுடையவளே, அரிய அணிகலனே, தெளிவாக வந்து கதவைத் திற.',
        '2.5': 'கன்றுகளுடன் கூடிய பல பசுக்கூட்டங்களைக் கறந்து, பகைவரின் வலிமை அழியப் போய்ப் போர்செய்யும் குற்றமற்ற ஆயர்களின் பொற்கொடியே, புற்றரவு போன்ற இடையுடைய புனமயிலே, வெளியே வா. உன் சுற்றத்துத் தோழிகள் எல்லோரும் வந்து உன் முற்றத்தில் புகுந்து முகில்வண்ணனின் பெயரைப் பாட, நீ அசையாமலும் பேசாமலும் இருக்கிறாய்; செல்வப் பெண்ணே, எதற்காக உறங்குகிறாய்?',
        '2.6': 'கன்றுக்கு இரங்கிக் கனைக்கும் இளம் கற்றெருமைகளின் மடியிலிருந்து நினைவுடன் பால் சொரிந்து இல்லத்தையே சேறாக்கும் நற்செல்வனின் தங்கையே, பனி தலையில் வீழ நாங்கள் உன் வாசற்கடையைப் பற்றிக்கொண்டு, சினத்தால் தென்னிலங்கை மன்னனை அழித்த மனத்துக்கினியவனைப் பாடியும் நீ வாய்திறக்கவில்லை. இப்போதாவது எழுந்திரு; இதென்ன பெருந்தூக்கம்? வீட்டார் அனைவரும் அறிந்துவிட்டனர்.',
        '2.7': 'பறவை வடிவ அசுரனின் வாயைப் பிளந்தவனும் கொடிய அரக்கனை நகத்தால் கிள்ளி எறிந்தவனுமான கண்ணனின் புகழைப் பாடிக்கொண்டு பிள்ளைகள் எல்லோரும் நோன்புக் களத்தில் புகுந்துவிட்டனர். வெள்ளி எழுந்து வியாழன் உறங்கிவிட்டது; பறவைகளும் கூவின. மான்போன்ற கண்ணுடையவளே, குளிரக் குளிர மூழ்கி நீராடாமல் படுக்கையில் கிடப்பாயோ? இந்த நன்னாளில் கபடத்தை விட்டுக் கலந்துகொள்.',
        '2.8': 'உங்கள் புழக்கடைத் தோட்டத்துக் குளத்தில் செங்கழுநீர் மலர்ந்து ஆம்பல் கூம்பிவிட்டது. செங்காவி ஆடையும் வெண்பற்களும் உடைய துறவியர் தங்கள் கோயிலில் சங்கு ஊத வருகிறார்கள். எங்களை முன்பே எழுப்புவேன் என்று வாய்பேசிய நங்கையே, நாணமில்லையா? பேச்சுத்திறமையுடையவளே, எழுந்திரு; சங்கும் சக்கரமும் ஏந்திய பெருங்கைகளையுடைய தாமரைக்கண்ணனைப் பாடு.',
        '2.9': '“எல்லே, இளங்கிளியே, இன்னும் உறங்குகிறாயா?” “பெண்களே, இப்படிக் கூர்மையாக அழைக்காதீர்கள்; வருகிறேன்.” “உன் பேச்சுத்திறமையை முன்பே அறிவோம்.” “திறமையுடையவர்கள் நீங்களே; நானே ஆகட்டும்.” “விரைவாக வா; உனக்கு என்ன சிறப்பு?” “எல்லோரும் வந்தார்களா?” “வந்தார்கள்; வந்து எண்ணிக்கொள்.” வலிய யானையைக் கொன்றவனும் பகைவரை அழிக்க வல்லவனுமான மாயனைப் பாடுவோம்.',
        '3.0': 'நாயகனாய் நின்ற நந்தகோபனின் கோயிலைக் காப்பவனே, கொடிகளும் தோரணமும் தோன்றும் வாயிலைக் காப்பவனே, மணிக்கதவின் தாளைத் திறவாய். ஆயர் சிறுமிகளாகிய எங்களுக்கு, ஒலிக்கும் பறையைத் தருவதாக மாயன் மணிவண்ணன் நேற்றே வாக்களித்தான். தூய்மையாக வந்தோம், அவனை எழுப்பப் பாடுவதற்கு. முன்பே வாயால் மறுத்துவிடாதே; அன்புடன் கதவின் தாளை நீக்குவாய்.',
        '3.1': 'ஆடை, தண்ணீர், உணவு ஆகியவற்றை அறமாக அளிக்கும் எம்பெருமானே, நந்தகோபாலா, எழுந்திரு. மென்மையான பெண்களுக்கெல்லாம் கொழுந்தே, குலவிளக்கே, எம்பெருமாட்டி யசோதையே, விழித்தெழு. வானைக் கிழித்து ஓங்கி உலகளந்த தேவர்கோமானே, உறங்காமல் எழுந்திரு. செம்பொன் கழலணிந்த செல்வனே, பலதேவா, நீயும் உன் தம்பியும் இனி உறங்காதீர்கள்.',
        '3.2': 'மதயானைபோல் புறமுதுகிடாத தோள்வலிமையுடைய நந்தகோபாலனின் மருமகளே, நப்பின்னாய், மணம் கமழும் கூந்தலுடையவளே, கதவைத் திற. கோழிகள் எங்கும் கூவிவிட்டன; மாதவிப் பந்தலின்மேல் குயில்கள் பலமுறை கூவுகின்றன. பந்து ஏந்திய விரல்களையுடையவளே, உன் மைத்துனனின் பெயரைப் பாடச் செந்தாமரைக் கையால் வளையல்கள் ஒலிக்க வந்து மகிழ்ந்து கதவைத் திற.',
        '3.3': 'குத்துவிளக்கு எரிய, தந்தக்கால் கட்டிலின்மேல் மெத்தென்ற பஞ்சசயனத்தில் ஏறி, கொத்தாக மலர்ந்த பூக்களைச் சூடிய நப்பின்னையின் கொங்கையின்மேல் மார்பை வைத்துக் கிடக்கும் மலர்மார்பனே, வாய்திற. மைதீட்டிய பெரிய கண்களையுடையவளே, நீ உன் மணாளனை எத்தனை நேரமும் துயிலெழ விடமாட்டாய்; அவனைச் சற்றும் பிரிந்திருக்க இயலாதவளாய் இருக்கிறாய். இது தத்துவமன்று, தகவுமன்று.',
        '3.4': 'முப்பத்து மூவர் அமரர்களுக்கு முன்சென்று அவர்களின் நடுக்கத்தைத் தவிர்க்கும் வீரனே, துயிலெழாய். நேர்மையுடையவனே, திறலுடையவனே, பகைவர்க்கு வெப்பம் தரும் விமலனே, துயிலெழாய். செப்புபோன்ற மென்முலையும் செவ்வாயும் சிறுஇடையும் உடைய நப்பின்னை நங்காய், திருவே, துயிலெழாய். விசிறியும் கண்ணாடியும் தந்து, உன் மணாளனைக் கொண்டு எங்களை இப்போதே நீராட்டுவாய்.',
        '3.5': 'ஏந்திய பாத்திரங்கள் பொங்கி வழியும்படி இடைவிடாது பால் சொரியும் வள்ளல் பெரும்பசுக்களை மிகுதியாகப் படைத்தவனின் மகனே, விழித்தெழு. ஊக்கமுடையவனே, பெரியவனே, உலகில் தோன்றி நின்ற சுடரே, துயிலெழாய். பகைவர் வலிமை இழந்து உன் வாசலில் வந்து உன் திருவடி பணிவதுபோல், நாங்கள் உன்னைப் போற்றிப் புகழ்ந்து வந்தோம்.',
        '3.6': 'அழகிய பெரிய உலகின் அரசர்கள் செருக்கு அழிந்து வந்து உன் பள்ளிக்கட்டிலின் கீழே கூட்டமாக இருப்பதுபோல் நாங்களும் வந்து கூடினோம். கிண்கிணியின் வாய்போல் மலர்ந்த தாமரைப்பூப் போன்ற உன் செங்கண்கள் சிறிது சிறிதாகவாவது எங்கள்மேல் விழிக்காதோ? சந்திரனும் சூரியனும் ஒருசேர எழுந்ததுபோல் அழகிய இரு கண்களாலும் எங்களை நோக்கினால் எங்கள் சாபம் நீங்கும்.',
        '4.0': 'மழைக்காலத்தில் மலைக்குகையில் அமர்ந்து உறங்கும் சீரிய சிங்கம் விழித்து, தீப்போல் விழித்துப் பார்த்து, மணம் மிக்க பிடரிமயிர் சிலிர்க்க எல்லாப் பக்கமும் உதறி, உடல் நிமிர்ந்து முழங்கிப் புறப்பட்டு வருவதுபோல், காயாம்பூ வண்ணனே, நீ உன் கோயிலிலிருந்து இங்கே எழுந்தருளி, கோப்புடைய சிறந்த சிங்காசனத்தில் அமர்ந்து, நாங்கள் வந்த காரியத்தை ஆராய்ந்து அருள்வாய்.',
        '4.1': 'அன்று இவ்வுலகை அளந்த உன் அடிகளுக்குப் போற்றி; அங்குச் சென்று தென்னிலங்கையை அழித்த உன் திறலுக்குப் போற்றி; சகடத்தை உதைத்து அழித்த உன் புகழுக்குப் போற்றி; கன்றை எறிகோலாகக் கொண்டு எறிந்த உன் கழலுக்குப் போற்றி; குன்றைக் குடையாக எடுத்த உன் குணத்திற்குப் போற்றி; வென்று பகைவரை அழிக்கும் உன் கையிலுள்ள வேலுக்குப் போற்றி. இவ்வாறு உன் வீரச்செயல்களைப் போற்றிப் பறை கொள்வதற்கு இன்று நாங்கள் வந்தோம்; இரங்கியருள்வாய்.',
        '4.2': 'ஒருத்தியின் மகனாய்ப் பிறந்து, அதே இரவில் ஒருத்தியின் மகனாய் ஒளிந்து வளர, அதைப் பொறுக்காமல் தீங்கு நினைத்த கஞ்சனின் எண்ணத்தைப் பிழைக்கச் செய்து அவன் வயிற்றில் நெருப்பாக நின்ற நெடுமாலே, உன்னை வேண்டி வந்தோம்; பறை தருவாயாயின், தகுந்த உன் செல்வத்தையும் வீரத்தையும் பாடி, துயரம் தீர்ந்து மகிழ்வோம்.',
        '4.3': 'மாலே, மணிவண்ணா, மார்கழி நீராடுவதற்கு மேலோர் செய்யும் செயல்களுக்கு வேண்டுவன என்ன என்று நீ கேட்பாயாயின், உலகெல்லாம் நடுங்க முழங்கும் பால்போன்ற வெண்மையுடைய உன் பாஞ்சசன்னியம் போன்ற சங்குகளும், மிகப் பெரிய பறையும், பல்லாண்டு இசைப்பாரும், அழகிய விளக்கும், கொடியும், மேற்கட்டியும் வேண்டும். ஆலிலையில் துயின்றவனே, அருள்வாய்.',
        '4.4': 'கூடாதவரையும் வெல்லும் சீர்மிகு கோவிந்தா, உன்னைப் பாடிப் பறைகொண்டு நாங்கள் பெறும் சம்மானம் நாடு புகழும் பரிசாக இருக்கும். சூடகம், தோள்வளை, தோடு, செவிப்பூ, பாடகம் முதலிய பல அணிகலன்களையும் நாங்கள் அணிவோம்; ஆடை உடுப்போம். அதன்பின் நெய் மூடும்படி பெய்து முழங்கை வழியே வழியும் பாற்சோற்றைக் கூடியிருந்து உண்டு குளிர்ந்து மகிழ்வோம்.',
        '4.5': 'பசுக்களின் பின்சென்று காட்டை அடைந்து உண்போம். அறிவொன்றும் இல்லாத ஆய்க்குலத்தில் நீ பிறக்கும் புண்ணியத்தை நாங்கள் உடையவர்கள். குறைவொன்றும் இல்லாத கோவிந்தா, உன்னோடு நமக்கிருக்கும் உறவை ஒழிக்க முயன்றாலும் ஒழியாது. அறியாத பிள்ளைகளான நாங்கள் அன்பினால் உன்னைச் சிறு பெயர்கள் சொல்லி அழைத்ததற்கும் சீறாமல் அருள்வாய்; இறைவா, பறையைத் தருவாய்.',
        '4.6': 'அதிகாலையில் வந்து உன்னைச் சேவித்து உன் பொற்றாமரை அடிகளைப் போற்றும் காரணத்தைக் கேள். பசுக்களை மேய்த்து உண்ணும் குலத்தில் பிறந்த நீ எங்கள் குற்றேவலை ஏற்காமல் போகக்கூடாது. கோவிந்தா, இன்று பறைகொள்ள மட்டும் நாங்கள் வரவில்லை. எப்போதும், ஏழேழு பிறவிக்கும் உன்னோடு உறவுடையவராவோம், உனக்கே தொண்டு செய்வோம். எங்கள் மற்ற ஆசைகளை மாற்றி அருள்வாய்.',
        '4.7': 'கப்பல்கள் செல்லும் கடலைக் கடைந்த மாதவனை, கேசவனை, நிலவு போன்ற திருமுகமுடைய செவ்வணிகலன் பூண்ட பெண்கள் சென்று வணங்கி அங்குப் பறை பெற்ற முறையை, அழகிய புதுவையில் பசுமையான தாமரைமாலை அணிந்த பட்டர்பிரானின் மகள் கோதை சொன்ன சங்கத் தமிழ்மாலை முப்பதையும் தவறாமல் இங்கு உரைப்பவர், நான்கு மலைபோன்ற தோள்களும் செங்கண்ணும் திருமுகமும் உடைய செல்வத் திருமாலின் திருவருளை எங்கும் பெற்று இன்புறுவர்.',
        '5.0': 'ஆடிப் பூரத்தில் உலகில் அவதரித்தவள் வாழ்க; திருப்பாவை முப்பதும் பாடியவள் வாழ்க; பெரியாழ்வார் பெற்றெடுத்த பெண்பிள்ளை வாழ்க; பெரும்பூதூர் மாமுனிவருக்குப் பின் வந்தவள் வாழ்க; நூற்று நாற்பத்து மூன்று பாடல்களைப் பாடியவள் வாழ்க; உயர்ந்த அரங்கனுக்குத் தன் மாலையை மகிழ்ந்து அளித்தவள் வாழ்க; மணம் கமழும் திருமல்லி நாட்டின் வளநாடி வாழ்க; வளமான புதுவை நகரத்துக் கோதையின் மலர்ப்பாதங்கள் வாழ்க.',
      },
    },
    'skanda-shashti-kavacham': {
      summary: 'பால தேவராய சுவாமிகள் இயற்றிய முருகனின் தமிழ்க் கவசம். வேலுடனும் மயிலுடனும் வருமாறு முருகனை அழைத்தல், தலை முதல் உறுப்புகளையும் நாளின் ஒவ்வொரு நேரத்தையும் வேல் காக்க வேண்டுதல், தீய சக்திகளையும் விலங்குகளையும் நோய்களையும் விரட்டுதல், ஓதுவதன் பலன் கூறுதல் ஆகியவை இதில் உள்ளன. கந்த சஷ்டியின் ஆறு நாட்களில் சிறப்பாக ஓதப்படுகிறது.',
      verses: {
        '0.0': 'இதைத் துதிப்பவர்களுக்கு வல்வினை போகும், துன்பம் போகும்; நெஞ்சில் பதிப்பவர்களுக்குச் செல்வம் பலித்து ஓங்கும்; நிஷ்டையும் கைகூடும். நிமலரின் அருளால் உண்டான கந்தர் சஷ்டி கவசம் இது.',
        '0.1': 'நெஞ்சே, தேவர்களின் துயரம் தீர்க்கப் போர் புரிந்த குமரனின் திருவடிகளை நினைப்பாயாக.',
        '1.0': 'சஷ்டியை நோக்கி, சரவணத்தில் தோன்றியவரும், நல்லோருக்கு உதவுபவரும், செங்கதிர் வேலை ஏந்தியவரும், இரு பாதங்களில் பலமணிச் சதங்கை இசைபாடக் கிண்கிணி ஆட, மனம் மயக்கும் நடனம் செய்யும் மயில்வாகனருமான முருகனை நினைக்கிறேன்.',
        '1.1': '“கையில் வேலால் என்னைக் காக்க” என்று வேண்டி அழைக்கிறேன்: “வர வர, வேலாயுதனே வருக; வருக வருக, மயிலோனே வருக; இந்திரன் முதலான எண்டிசையினரும் போற்றும் மந்திர வடிவேலே, வருக வருக.”',
        '1.2': 'வாசவன் மருகா, வருக வருக; அன்புமிகு குறமகள் நினைவில் உறைபவனே வருக; ஆறுமுகம் படைத்த ஐயா வருக; நீறிடும் வேலவன் நித்தம் வருக; சிரகிரி வேலவன் சீக்கிரம் வருக.',
        '1.3': 'சரவணபவனே சடுதியில் வருக; அடுத்து “ரஹண பவச ரரரர ரரர”, “ரிஹண பவச ரிரிரிரி ரிரிரி”, “விணபவ சரஹண வீரா நமோ நம”, “நிபவ சரஹண நிறநிற நிறென” என்னும் பீஜ ஒலிகளால் ஆறெழுத்து மந்திரத் தலைவனை அழைக்கிறேன்.',
        '1.4': 'வருக வருக, அசுரர் குடிகெடுத்த ஐயா வருக; என்னை ஆளும் இளையோன் கையில் பன்னிரண்டு ஆயுதமும் பாசமும் அங்குசமும், பரந்த பன்னிரு விழிகளும் ஒளிர, விரைந்து என்னைக் காக்க வேலோனே வருக.',
        '1.5': '“ஐயும் கிலியும் சௌவும்” என்னும் பீஜங்கள் முறையே ஒளிவிட்டு, சண்முகனின் ஒப்பற்ற ஒளிக்கு ஈடான சுடராக என் முன் நிலைத்து நித்தமும் ஒளிரட்டும். குண்டலியின் தலைவனான சிவகுகன் தினமும் வருக.',
        '2.0': 'ஆறுமுகமும் அணிமுடி ஆறும், நீறிட்ட நெற்றியும் நீண்ட புருவமும், பன்னிரு கண்ணும் பவளச் செவ்வாயும், நெற்றியில் நவமணிச் சுட்டியும், பன்னிரு செவியில் குண்டலமும், பன்னிரு திண்புயமும் அழகிய மார்பும், பல அணிகளும் பதக்கங்களும், நவரத்தின மாலையும் தரித்து வருக.',
        '2.1': 'முப்புரி நூலும் முத்தணி மார்பும், அழகிய வயிறும் உந்தியும், துவளும் இடையில் சுடரொளிப் பட்டும், நவரத்தினம் பதித்த நற்சீராவும், இரு தொடையழகும் இணைந்த முழங்காலும் உடையவனாய் வருக.',
        '2.2': 'திருவடியில் சிலம்பொலி முழங்க, “செககண செககண செககண செகண”, “மொகமொக மொகமொக மொகமொக மொகென”, “நகநக நகநக நகநக நகென”, “டிகுகுண டிகுடிகு டிகுகுண டிகுண” என்னும் ஒலிகளுடன் வருக.',
        '2.3': '“ரரரர ரரரர ரரரர ரரர”, “ரிரிரிரி ரிரிரிரி ரிரிரிரி ரிரிரி”, “டுடுடுடு டுடுடுடு டுடுடுடு டுடுடு”, “டகுடகு டிகுடிகு டங்கு டிங்குகு” என்னும் ஒலிகளுடன்.',
        '2.4': 'விந்து விந்து, மயிலோனே விந்து; முந்து முந்து, முருகவேளே முந்து; என்னை ஆளும் ஏரகச் செல்வமே, மைந்தனே, நான் வேண்டும் வரத்தை மகிழ்ந்து உதவுபவனே.',
        '3.0': '“லாலா லாலா லாலா”, “லீலா லீலா லீலா” என்னும் ஒலிகளுடன், லீலா வினோதனே: உன் திருவடியை உறுதியென எண்ணி உன் இணையடியில் வைத்த என் தலையைக் காக்க; என் உயிர்க்கு உயிராம் இறைவன் காக்க; பன்னிரு விழியால் பாலன் என்னைக் காக்க; அடியேன் முகத்தை அழகுவேல் காக்க.',
        '3.1': 'நீறணிந்த நெற்றியைப் புனிதவேல் காக்க; கதிர்வேல் இரண்டும் கண்ணினைக் காக்க; விதிசெவி இரண்டையும் வேலவர் காக்க; நாசிகள் இரண்டையும் நல்வேல் காக்க; பேசும் வாயைப் பெருவேல் காக்க.',
        '3.2': 'முப்பத்திரு பல்லை முனைவேல் காக்க; செப்பிய நாவைச் செவ்வேல் காக்க; கன்னம் இரண்டையும் கதிர்வேல் காக்க; என் இளங்கழுத்தை இனியவேல் காக்க; மார்பை ரத்ன வடிவேல் காக்க.',
        '3.3': 'சேரிள முலைமார் திருவேல் காக்க; வடிவேல் இருதோளை வளம்பெறக் காக்க; பிடரிகள் இரண்டையும் பெருவேல் காக்க; அழகுடன் முதுகை அருள்வேல் காக்க; பழுபதினாறையும் பருவேல் காக்க.',
        '3.4': 'வெற்றிவேல் வயிற்றை விளங்கவே காக்க; சிற்றிடை அழகுறச் செவ்வேல் காக்க; நாணாம் கயிற்றை நல்வேல் காக்க; ஆண்குறி இரண்டையும் அயில்வேல் காக்க; பிட்டம் இரண்டையும் பெருவேல் காக்க.',
        '3.5': 'வட்டக் குதத்தை வல்வேல் காக்க; பணைத்தொடை இரண்டையும் பருவேல் காக்க; கணைக்கால் முழந்தாளைக் கதிர்வேல் காக்க; ஐவிரல் அடிகளை அருள்வேல் காக்க; கைகள் இரண்டையும் கருணைவேல் காக்க.',
        '3.6': 'முன்கை இரண்டையும் முரண்வேல் காக்க; பின்கை இரண்டுடன் பின்னவளாகிய வள்ளி இருக்க; நாவில் சரஸ்வதி நற்றுணையாக; நாபிக் கமலத்தை நல்வேல் காக்க; முப்பால் நாடியை முனைவேல் காக்க.',
        '3.7': 'எப்பொழுதும் எனை எதிர்வேல் காக்க; அடியேன் வசனம் அசைவுள நேரம் கடுகவே வந்து கனகவேல் காக்க; வரும் பகலில் வச்சிரவேல் காக்க; அரையிருளில் அணையவேல் காக்க; ஏமத்திலும் யாமத்திலும் எதிர்வேல் காக்க; தாமதம் நீக்கிச் சதுர்வேல் காக்க.',
        '3.8': 'காக்க காக்க கனகவேல் காக்க; நோக்க நோக்க நொடியினில் நோக்க; தாக்க தாக்க தடையறத் தாக்க; பார்க்க பார்க்க பாவம் பொடிபட; பில்லி சூனியம் பெரும்பகை அகல.',
        '4.0': 'வல்ல பூதமும் வலாஷ்டிகப் பேய்களும், அல்லற் படுத்தும் அடங்கா முனியும், பிள்ளைகள் தின்னும் புழக்கடை முனியும், கொள்ளிவாய்ப் பேய்களும் குறளைப் பேய்களும், பெண்களைத் தொடரும் பிரமராட்சதரும்:',
        '4.1': 'அடியனைக் கண்டு அலறிக் கலங்கட்டும்: இரிசிக் காட்டேரி இத்துன்ப சேனையும், எல்லிலும் இருட்டிலும் எதிர்ப்படும் அண்ணரும், கனபூசை கொள்ளும் காளியோடு அனைவரும், விட்டாங் காரரும் மிகுபல பேய்களும், தண்டியக் காரரும் சண்டாளர்களும்.',
        '4.2': 'என் பெயர் சொல்லவும் இடிவிழுந்து ஓடட்டும்: ஆனை அடியினில் புதைத்த அரும்பாவைகளும், பூனை மயிரும் பிள்ளைகள் என்பும், நகமும் மயிரும் நீண்முடி மண்டையும்.',
        '4.3': 'பாவைகளுடனே பலகலசத்துடன், மனையிற் புதைத்த வஞ்சனை தனையும், ஒட்டியச் செருக்கும் ஒட்டியப் பாவையும், காசும் பணமும் காவுடன் சோறும், ஓதும் அஞ்சனமும் ஒருவழிப் போக்கும்:',
        '4.4': 'அடியனைக் கண்டால் அலைந்து குலைந்திட; மாற்றார் வஞ்சகர் வந்து வணங்கிட; காலதூதர் எனைக் கண்டால் கலங்கிட; அஞ்சி நடுங்கிட அரண்டு புரண்டிட; வாய்விட்டு அலறி மதிகெட்டு ஓட.',
        '4.5': 'படியினில் முட்டப் பாசக் கயிற்றால் கட்டு; உடல் கதறிடக் கட்டு; கால்கை முறியக் கட்டி உருட்டு; கட்டு கட்டு கதறிடக் கட்டு; முட்டு முட்டு விழிகள் பிதுங்கிட.',
        '4.6': 'செக்கு செக்கு செதில் செதிலாக; சொக்கு சொக்கு சூர்ப்பகைச் சொக்கு; குத்து குத்து கூர்வடிவேலால்; பற்று பற்று பகலவன் தணலெரி; தணலெரி தணலெரி தணலது ஆக; விடு விடு வேலை, வெருண்டது ஓட.',
        '4.7': 'புலியும் நரியும் புன்னரி நாயும், எலியும் கரடியும் இனித்தொடர்ந்து ஓட; தேளும் பாம்பும் செய்யான் பூரான், கடிவிட விஷங்கள் கடித்துயரங்கம் ஏறிய விஷங்கள் எளிதினில் இறங்க.',
        '4.8': 'ஒளிப்பும் சுளுக்கும் ஒருதலை நோயும், வாதம் சயித்தியம் வலிப்புப் பித்தம், சூலை சயம் குன்மம் சொக்குச் சிரங்கு, குடைச்சல் சிலந்தி குடல்விப் பிரிதி, பக்கப் பிளவை படர்தொடை வாழை ஆகிய நோய்கள் நீங்க.',
        '4.9': 'பற்குத்து அரணை பருஅரை யாப்பும், எல்லாப் பிணியும் என்றனைக் கண்டால் நில்லாது ஓட நீ எனக்கு அருள்வாய்; ஈரேழ் உலகமும் எனக்கு உறவாக, ஆணும் பெண்ணும் அனைவரும் எனக்காக, மண்ணாள் அரசரும் மகிழ்ந்து உறவாகவும் அருள்வாய்.',
        '5.0': 'உன்னைத் துதிக்க உன் திருநாமம்: சரவணபவனே, சைலொளிபவனே, திரிபுரபவனே, திகழொளிபவனே, பரிபுரபவனே, பவமொழிபவனே, அரிதிருமருகா, அமராபதியைக் காத்துத் தேவர்களைக் கடுஞ்சிறை விடுத்தவனே.',
        '5.1': 'கந்தா, குகனே, கதிர்வேலவனே, கார்த்திகை மைந்தா, கடம்பா, கடம்பனை, இடும்பனை அழித்த இனியவேல் முருகா, தணிகாசலனே, சங்கரன் புதல்வா, கதிர்காமத் துறை கதிர்வேல் முருகா, பழநிப் பதிவாழ் பால குமாரா, ஆவினன் குடிவாழ் அழகிய வேலா, செந்தின்மாமலை உறும் செங்கல்வராயா, சமராபுரிவாழ் சண்முகத் தரசே.',
        '5.2': 'காரார் குழலாள் கலைமகள் நன்றாய் என்நா இருக்க, யான் உனைப் பாட; எனைத்தொடர்ந்திருக்கும் எந்தை முருகனைப் பாடினேன், ஆடினேன், பரவசமாக; ஆடினேன், நாடினேன், ஆவினன் பூதியை.',
        '5.3': 'நேசமுடன் யான் நெற்றியில் அணியப், பாசவினைகள் பற்றது நீங்கி, உன்பதம் பெறவே உன்னருளால், அன்புடன் ரக்ஷி; அன்னமும் சொன்னமும் மெத்த மெத்தாக வேலாயுதனார் தர; சித்திபெற்று அடியேன் சிறப்புடன் வாழ்க.',
        '6.0': 'வாழ்க வாழ்க மயிலோன் வாழ்க; வாழ்க வாழ்க வடிவேல் வாழ்க; வாழ்க வாழ்க மலைக்குரு வாழ்க; வாழ்க வாழ்க மலைக்குறமகளுடன்; வாழ்க வாழ்க வாரணத்துவசம்; வாழ்க வாழ்க என் வறுமைகள் நீங்க.',
        '6.1': 'எத்தனை குறைகள், எத்தனை பிழைகள், எத்தனை அடியேன் செய்தாலும், பெற்றவன் நீ, குரு; பொறுப்பது உன் கடன்; பெற்றவள் குறமகள்; பிள்ளை என்று அன்பாய்ப் பிரியம் அளித்து, மைந்தன் என்மீது உன் மனம் மகிழ்ந்து அருளி, தஞ்சம் என்று அடியார் தழைத்திட அருள்செய்; நீ விரும்பிய கந்தர் சஷ்டி கவசத்தை ஏற்றருள்.',
        '6.2': 'பாலன் தேவராயன் பகர்ந்ததைக் காலையிலும் மாலையிலும் கருத்துடன் நாளும், ஆசாரத்துடன் அங்கந் துலக்கி, நேசமுடன் ஒரு நினைவதுவாகிக், கந்தர் சஷ்டிக் கவசம் இதனைச் சிந்தை கலங்காது தியானிப்பவர்கள் (பின்வரும் பலன்களைப் பெறுவர்).',
        '7.0': 'ஒருநாள் முப்பத்தாறுருக் கொண்டு ஓதியே செபித்து உகந்து நீறணிய, அஷ்டதிக்குள்ளோர் அடங்கலும் வசமாய், திசைமன்னர் எண்மர் செயலது அருளுவர், மாற்றலரெல்லாம் வந்து வணங்குவர்.',
        '7.1': 'நவகோள் மகிழ்ந்து நன்மை யளித்திடும்; நவமதன் எனவும் நல்லெழில் பெறுவர்; எந்த நாளும் ஈரெட்டாய் வாழ்வர்; கந்தர் கை வேலாம் கவசத்தடியை வழியாற் காண மெய்யாய் விளங்கும்.',
        '7.2': 'விழியாற் காண வெருண்டிடும் பேய்கள்; பொல்லாதவரைப் பொடிப்பொடி யாக்கும்; நல்லோர் நினைவில் நடனம் புரியும்; சர்வ சத்துரு சங்காரத் தடி.',
        '8.0': 'அறிந்தென துள்ளம் அஷ்டலட்சுமிகளில், வீரலட்சுமிக்கு விருந்துணவாகச், சூரபத்மாவைத் துணித்த கையதனால், இருபத்தேழ்வர்க்கு உவந்தமுதளித்த, குருபரன் பழநிக் குன்றினிலிருக்கும் சின்னக் குழந்தை சேவடி போற்றி.',
        '8.1': 'சின்னக் குழந்தை சேவடி போற்றி; எனைத்தடுத்து ஆட்கொள என்றன துள்ளம் மேவிய வடிவுறும் வேலவா போற்றி; தேவர்கள் சேனாபதியே போற்றி; குறமகள் மனமகிழ் கோவே போற்றி; திறமிகு திவ்விய தேகா போற்றி.',
        '8.2': 'இடும்பாயுதனே இடும்பா போற்றி; கடம்பா போற்றி; கந்தா போற்றி; வெட்சி புனையும் வேளே போற்றி; உயர்கிரி கனகசபைக்கோர் அரசே; மயில் நடமிடுவோய், மலரடி சரணம்; சரணம் சரணம் சரஹணபவ ஓம்; சரணம் சரணம் சண்முகா சரணம்.',
      },
    },
    'anjaneya-dandakam': {
      summary: 'அனுமனைப் புகழ்ந்து தெலுங்கில் அமைந்த நீண்ட, இடைவெளியற்ற தண்டகம். தொடக்க வணக்கங்களுக்குப் பின் சுக்ரீவனுக்கும் இராமனுக்கும் அனுமன் செய்த தொண்டுகளை நினைவுகூர்கிறது: சீதையைக் கண்டது, இலங்கையை எரித்தது, சஞ்சீவியைக் கொண்டுவந்தது, அயோத்தி முடிசூட்டு. பேய், பிசாசு அச்சத்திலிருந்து காக்க வேண்டும் என்ற பிரார்த்தனையுடனும் மீண்டும் மீண்டும் வணக்கங்களுடனும் முடிகிறது. செவ்வாய், சனிக்கிழமைகளில் சிறப்பாக ஓதப்படுகிறது.',
      verses: {
        '0.0': 'மகிழ்ச்சியுடைய ஆஞ்சநேயனை, ஒளிமிக்க தெய்வீக உடலுடையவனை, புகழ் அளிப்பவனை வணங்குகிறேன்; வாயுபுத்திரனை, வால் உடைய உடலினனை வணங்குகிறேன்; தூய்மையானவனை வணங்குகிறேன்; சூரியனின் நண்பனை, ருத்திர வடிவினனை, பிரம்மதேஜஸ் உடையவனை வணங்குகிறேன் என்று.',
        '0.1': 'காலையிலும் மாலையிலும் உன் திருநாமத்தைப் பாடி, உன் வடிவை வர்ணித்து, உன்மீது இந்த ஒரு தண்டகத்தை இயற்ற, உன் திருமேனியை மனத்தில் கொண்டு உன் அழகை எண்ணி, உன் அடியாரின் அடியேனாகவும் இராம பக்தனாகவும் உன்னை வழிபடுகிறேன்.',
        '0.2': 'உன் அருட்பார்வையால் என்னைப் பார்த்தால், மகிழ்ந்தால், என் முறையீட்டைக் கேட்டால், என்னைக் காத்தால், அஞ்சனாதேவியின் கருவில் பிறந்த தேவனே, உன்னை நினைக்க நான் எம்மாத்திரம்?',
        '1.0': 'கருணையுடன் பார்த்து, வள்ளலாய்க் காத்து, அருகில் நின்றாய். முன்பு சுக்ரீவனுக்கு மந்திரியாக, தலைவனின் பணிக்காகச் சென்று, இராமலட்சுமணரைக் கண்டு விசாரித்து, எல்லோர்க்கும் தலைவனை வணங்கி, சூரியனின் மகனான சுக்ரீவனை அவனுக்குத் தொண்டனாக்கினாய்.',
        '1.1': 'வாலியைக் கொல்லச் செய்து, காகுத்ஸ்த குலத் திலகனான இராமன் உன்னைக் கருணையுடன் நோக்கினான். கிஷ்கிந்தைக்கு வந்து, இராமன் பணிக்காக இலங்கைக்குச் சென்று, இலங்கிணியைக் கொன்று இலங்கையை எரித்தாய்.',
        '1.2': 'பூமகள் சீதையைக் கண்டு மகிழ்ச்சி பொங்கி, அவளுக்கு மோதிரம் அளித்து, அவளது ரத்தினத்தை எடுத்துவந்து இராமனிடம் தந்து அவனை மகிழ்வித்தாய். சுக்ரீவன், அங்கதன், ஜாம்பவான், நளன், நீலன் ஆகியோருடன் அந்தப் பாலத்தைக் கடந்து, வானரப் பெரும் படைகள் அரக்கர்களை அழித்தன.',
        '1.3': 'அப்போது இராவணன் காலாக்னி ருத்திரனைப்போல் வந்து, பெருஞ்சக்தி ஆயுதத்தை எறிந்து இலட்சுமணனை மூர்ச்சையடையச் செய்ய, அதே நேரத்தில் நீ சஞ்சீவியைக் கொண்டுவந்து சௌமித்திரிக்கு அளித்து அவன் உயிரைக் காத்தாய்.',
        '1.4': 'கும்பகர்ணன் முதலிய வீரர்களுடன் போர் நடந்து, இராமனின் அம்புத்தீ அவர்கள் அனைவரையும் இராவணனையும் அழிக்க, உலகங்கள் மகிழ்ந்திருந்த வேளையில், நீ விபீஷணனை மகிழ்ச்சியுடன் அழைத்து வந்து முடிசூட்டச் செய்தாய்.',
        '1.5': 'சீதா மகாதேவியை அழைத்துவந்து இராமனிடம் ஒப்படைத்தாய். பின்னர் அயோத்தி நகரில் நுழைந்து முடிசூட்டு விழா சிறப்பாக நடைபெற, “உன்னைவிட எனக்கு அன்பானவர் யாருமில்லை” என்று அவன் உன்னைப் பெருமைப்படுத்தினான்.',
        '2.0': 'இராம பக்தி சிறக்க உன்னை வழிபட்டு உன் புகழ்ப் பாடல்களைப் பாடினால், பாவங்கள் விலகுமா, அச்சங்கள் தீருமா, பாக்கியங்கள் உண்டாகுமா, சாம்ராஜ்யங்களும் செல்வங்களும் கிட்டுமா?',
        '2.1': 'வானர வடிவினனே, பக்தரின் கற்பகமே, புண்ணிய சஞ்சாரியே, தீரனே, வீரனே; நீயே எல்லாம் என்று கருதி, தாரக பிரம்ம மந்திரத்தை உறுதியுடன் ஓதி, வஜ்ர உடல் தாங்கி, “ஸ்ரீராம ஸ்ரீராம” என்று தூய மனத்துடன் எப்போதும் தவறாமல் நினைக்கிறேன். என் நாவில் இருந்துகொண்டு, மூவுலகும் சுற்றும் உன் நீண்ட உடலுடன், இராமநாமத் தியானத்துடன், பிரம்ம தேஜஸுடன், உக்கிரச் சுடர்க் கொந்தளிப்புடன், வீர அனுமனே:',
        '2.2': 'ஓங்கார ஒலியுடன், பேய் பிசாசுகளையும் பெரும் பிசாசுகளையும் சாகினி டாகினி முதலானோரையும் காற்றுப் பேய்களையும் உன் வாலால் சுற்றி, தரையில் அடித்து, உன் முஷ்டிப் பிடிகளாலும் புஜங்களாலும் மயிர்த் துண்டுகளாலும் முறித்து, காலாக்னி ருத்திரனாகி, பிரம்மப் பிரபையுடன் ஒளிரும் உன் தெய்வீக ஒளியைக் கண்டு, “வா வா என் செல்ல நரசிங்கமே” என்று அருட்பார்வையால் நோக்கி என்னை ஆண்டுகொள்வாய், என் தலைவனே ஆஞ்சநேயா.',
        '3.0': 'எப்போதும் பிரம்மசாரியான உனக்கு வணக்கம்; வாயுபுத்திரனுக்கு மீண்டும் மீண்டும் வணக்கம்; உனக்கு வணக்கம்.',
      },
    },
    'annamacharya-brahma-kadigina-padamu': {
      summary: 'பிரம்மன் கழுவிய, பூமியையும் வானையும் அளந்த, மகாபலியை அழுத்திய, அகலிகையின் பாவத்தை நீக்கிய, காளியன் படத்தில் ஆடிய, திருமகள் பிடிக்கும், வேங்கடகிரி காட்டும் பரமபதமான இறைவனின் திருவடிகளை அன்னமாசாரியர் போற்றுகிறார். முகாரி ராகத்தில் பாடப்படுகிறது.',
      verses: {
        '0.0': 'பிரம்மன் கழுவிய திருவடி; தானே பரம்பொருளான திருவடி.',
        '1.0': 'மகிழ்ந்து பூமியை அளந்த உன் திருவடி, மகாபலியின் தலைமேல் வைத்த திருவடி, வானைத் தாண்டி உதைத்த திருவடி, இந்திரனைக் காத்த திருவடி.',
        '1.1': 'அந்தப் பெண்ணின் (அகலிகையின்) பாவத்தைக் கழுவிய திருவடி, பாம்பின் தலையில் வைத்த திருவடி, திருமகள் அன்புடன் பிடிக்கும் திருவடி, குதிரை வடிவத்தின் (கல்கியின்) திருவடி.',
        '1.2': 'சிறந்த யோகிகளுக்குப் பலவிதங்களில் பரம பலனை அளிக்கும் உன் திருவடி; திருவேங்கடகிரி நிலையான புகலிடம் என்று காட்டிய பரமபதம் உன் திருவடியே.',
      },
    },
    'annamacharya-cheri-yasodaku': {
      summary: 'யசோதையின் அருகிலுள்ள இந்தக் குழந்தையே பிரம்மனின் தந்தையும் உலகத் தலைவனும்; அவன் பார்வையால் சூரிய சந்திரர் ஒளிர்கிறார்கள், அவன் மூச்சு வேதங்களும் கடலும். இறுதியில் அவன் சரணடைந்தோருக்கு அடைக்கலமான ஸ்ரீ வேங்கடேசன் என்று வெளிப்படுகிறது. மோகன ராகத்தில் பாடப்படுகிறது.',
      verses: {
        '0.0': 'யசோதையிடம் வந்த இந்தக் குழந்தையே உலக பிரம்மனுக்கும் தந்தை.',
        '1.0': 'அவன் பார்த்தால் சூரிய சந்திரருக்கு ஒளி சேர்க்கும் நற்குணன்; நிற்கும் இடத்திலேயே எல்லா தெய்வங்களையும் தோற்றுவிக்கும் தேவர்களின் மூலம் இவனே பாருங்கள்.',
        '1.1': 'அவன் பேசினால் கோடி கோடி அண்டங்கள் தோன்றும் குணக்குவியல்; அவன் ஒழுங்கான மூச்சுகளிலிருந்து எல்லா வேதங்களும் அதிசயக் கடலும் வெளிப்படுகின்றன.',
        '1.2': 'எதிரிலுள்ள மோகன வடிவால் ஆத்மாக்களைப் பொங்கச் செய்யும் பெருந்தலைவன் இவன்; எங்களைப் போன்ற சரணடைந்தோருக்கு அடைக்கலமாகிய ஸ்ரீ வேங்கடாதிபன் இவனே.',
      },
    },
    'annamacharya-muddugare-yashoda': {
      summary: '“இரத்தினப் பாடல்”: யசோதையின் முற்றத்து முத்து, ஆய்ச்சியர் உள்ளங்கை மாணிக்கம், கம்சனின் சவாலுக்கு வைரம், மரகதம், பவளம், கோமேதகம், வைடூரியம், புஷ்பராகம், நீலம், பாற்கடலின் தெய்வீக ரத்தினம் என்று கண்ணனை வர்ணித்து, ஸ்ரீ வேங்கடாத்திரி பத்மநாபனில் முடிகிறது. குறிஞ்சி ராகத்தில் பாடப்படுகிறது.',
      verses: {
        '0.0': 'யசோதையின் முற்றத்து அழகிய முத்து இவன்; சீர்படுத்த முடியாத மகிமையுடைய தேவகியின் மகன்.',
        '1.0': 'சின்னஞ்சிறு ஆய்ச்சியரின் உள்ளங்கை மாணிக்கம், பிடிவாதக் கம்சனுக்கு வைரம், மூவுலகின் ஒளிகொண்ட மரகத மணி, எங்கள் அருகிலிருக்கும் சின்னக் கண்ணன்.',
        '1.1': 'காதல் விளையாட்டில் ருக்மிணிக்கு நிறம் கொண்ட இதழ்ப் பவளம், கோவர்த்தன அளவுக்கேற்ற கோமேதகம், எப்போதும் சங்கு சக்கரங்களுக்கிடையே வைடூரியம், எங்களுக்குப் புகலிடமாய்க் காக்கும் தாமரைக்கண்ணன்.',
        '1.2': 'காளியனின் தலைகளின்மேல் மூடிய புஷ்பராகம், ஆளும் ஸ்ரீ வேங்கடாத்ரியின் இந்திரநீலம், பாற்கடலில் பிரியாத தெய்வீக ரத்தினம், சிறுவனைப்போல் திரியும் பத்மநாபன்.',
      },
    },
    'annamacharya-jo-achyutananda': {
      summary: 'அன்னமாசாரியரின் மிகப் பிரபலமான தாலாட்டு. “ஜோ ஜோ” என்ற பல்லவி கண்ணனைத் தூங்க வைக்கிறது; சரணங்கள் அவனது குழந்தைப் பருவத்தையும் பிந்தைய செயல்களையும் சொல்கின்றன: வெண்ணெய் திருடுதல், ஆய்ச்சியர் முறையீடுகள், கோவர்த்தனம் தூக்கல், கம்ச வதம். கடைசிச் சரணம் தாளப்பாக்க அன்னமய்யாவின் பெயரைக் கூறி எல்லோருக்கும் மங்களம் வேண்டுகிறது. காபி ராகத்தில் பாடப்படுகிறது.',
      verses: {
        '0.0': 'ஜோ அச்சுதானந்தா, ஜோ ஜோ முகுந்தா; வா பரமானந்தா, ராமா, கோவிந்தா; ஜோ ஜோ, ஜோ ஜோ.',
        '1.0': 'நந்தனின் வீடு சேர்ந்து அழகுடன், நிலவுமுகத்துப் பெண்கள் உனக்குப் பணிவிடை செய்ய, அவர்கள் வீடுகளில் அழகாக விளையாடி, கால்நடைகளின் திருடனே, எங்கள் செல்ல ரங்கா, ஜோ ஜோ.',
        '1.1': 'பாற்கடலில் பள்ளிகொண்டாய்; முனிவர்களுக்கு அபயம் அளித்தாய்; வசுதேவருக்கு நன்மையாகப் பிறந்தாய்; குழந்தையாயிருந்தும் கோபாலனானாய்.',
        '1.2': 'உறைந்த ஆடையைத் தின்று புதுமருமகள் வாயில் தடவினான்; மாமியார் கேட்டபோது, “இவளே திருடி, அடி” என்று உறுதியாகச் சொன்னான்.',
        '1.3': 'ஆயர் வீடுகளுக்கு விரைந்து சென்று பானைகளிலிருந்த நெய்யை மிகுதியாகக் குடித்தாய். பெண்களை இப்படிச் சீண்டித் துன்புறுத்துவது முறையா? இத்தகைய குறும்புகள் செய்வது தகுமா?',
        '1.4': 'ரேபள்ளிப் பெண்கள் எல்லோரும் கோபத்துடன்: “கோபம்மா, உன் மகன் எங்கள் வீடுகளில் மாலையிலேயே வந்து எங்கள் மானத்தைக் கெடுத்துவிட்டான்; என்ன சொல்வோம் அம்மா?”',
        '1.5': 'ஒருவனின் மனைவியைக் கொண்டு வந்து இன்னொருவனின் அருகில் வைத்து, சண்டைகள் மூட்டி, தம்பதிகளைப் பிடித்து, பகலின் நான்கு ஜாமமும் சிறுவனாயிருந்து, மன்மதனைப்போல் பெண்களின் கைகளைப் பிடித்து.',
        '1.6': 'கோவர்த்தன மலையையே குடையாகப் பிடித்து, செருக்கிய கம்சனை வீழ்த்தி, மதுராபுரியைக் கைப்பற்றி மிடுக்குடன் ஆண்ட தேவகியின் மகனே.',
        '1.7': 'மன்மதனைப் பெற்ற எங்கள் செல்வமே, இங்கே வா; பொன் கிண்ணத்தில் பால் ஊற்றியிருக்கிறார்கள். நீ திருடன் என்று பெண்கள் கொதிக்கிறார்கள்; முற்றத்தில் விளையாடு, மோகன வடிவனே, ஜோ ஜோ.',
        '1.8': 'தாளப்பாக்க அன்னமய்யா மிகுந்த அன்புடன் அலங்கார நடையில் பாடிய இந்தத் தாலாட்டு; எல்லாச் செல்வங்களும் உனதாகுக; திருப்பதி மதனகோபாலனுக்கு மங்களம், ஜோ ஜோ.',
      },
    },
    'annamacharya-nanati-batuku': {
      summary: 'துறவுப் பாடல்: அன்றாட வாழ்வு ஒரு நாடகம்; பிறப்பும் இறப்புமே உண்மை; உண்பதும் உடுப்பதும் புண்ணிய பாவங்களும் காலம் கழிவதும் நாடகத்தின் பகுதிகளே; வேங்கடேஸ்வரனின் ஆட்சியில் வானுக்கும் மேலானதே முக்தி. ரேவதி ராகத்தில் பாடப்படுகிறது.',
      verses: {
        '0.0': 'அன்றாட வாழ்க்கை ஒரு நாடகம்; காணாமலே கண்டதே கைவல்யம்.',
        '1.0': 'பிறப்பு உண்மை, இறப்பு உண்மை; நடுவிலுள்ள செயல் நாடகம். எதிரே இருப்பது உலகம்; இறுதியில் இருப்பது கைவல்யம்.',
        '1.1': 'உண்ணும் சோறும் உடுக்கும் ஆடையும் நடுவிலுள்ள செயல், நாடகம். மடியில் கட்டிக்கொண்ட இருவகைக் கர்மங்களின் எல்லையைத் தாண்டும்போதே கைவல்யம்.',
        '1.2': 'பாவம் தீராது, புண்ணியம் முடியாது; சிரித்துச் சிரித்துக் கழியும் காலம் நாடகம். மேலே ஸ்ரீ வேங்கடேஸ்வரனின் ஆட்சி; வானுக்கு மேலேயுள்ளதே கைவல்யம்.',
      },
    },
    'annamacharya-tandanana-ahi': {
      summary: '“பிரம்மம் ஒன்றே”: நடன லயமுள்ள “தந்தனானா” பல்லவியைத் தொடர்ந்து சரணங்கள், அரசன் உறக்கமும் பணியாள் உறக்கமும் ஒன்றே, அந்தணனும் புலையனும் நிற்கும் நிலம் ஒன்றே, தேவர்க்கும் புழுக்கும் இன்பம் ஒன்றே, பசி ஒன்றே, யானைமேலும் நாய்மேலும் வெயில் ஒன்றே, புண்ணியருக்கும் பாவிக்கும் வேங்கடேசன் நாமம் ஒன்றே என்று கூறுகின்றன. பௌளி ராகத்தில் பாடப்படுகிறது.',
      verses: {
        '0.0': 'தந்தனானா, அஹி, தந்தனானா, புரே, தந்தனானா, பளா, தந்தனானா (நடன ஒலிகள்). பிரம்மம் ஒன்றே, பரப்பிரம்மம் ஒன்றே.',
        '1.0': 'இதில் உறுதியான உயர்வு தாழ்வு இல்லை; எல்லோருக்கும் ஸ்ரீஹரியே உள்ளுறை ஆத்மா. இதிலுள்ள உயிர்க்குலம் முழுதும் ஒன்றே; எல்லோருக்கும் ஸ்ரீஹரியே அந்தராத்மா.',
        '1.1': 'நிறைவான அரசன் தூங்கும் தூக்கம் ஒன்றே; அருகிலுள்ள பணியாளின் தூக்கமும் அதுவே. சிறந்த அந்தணன் மிதிக்கும் நிலம் ஒன்றே; புலையன் நடக்கும் நிலமும் அதுவே.',
        '1.2': 'அன்பிற்குரிய தேவர்களின் இன்பமும் பெரிய புழு பூச்சி விலங்குகளின் இன்பமும் ஒன்றே; பகலும் இரவும் செல்வந்தனுக்கும் ஒன்றே, ஏழைக்கும் அவையே.',
        '1.3': 'உயர்ந்த உணவை உண்ணும் பசி ஒன்றே; தாழ்ந்த உணவை உண்ணும் பசியும் அதுவே. நாற்றத்தின்மேல் வீசும் காற்று ஒன்றே; நறுமணத்தின்மேல் வீசும் காற்றும் அதுவே.',
        '1.4': 'யானைமேல் காயும் வெயில் ஒன்றே; நிலத்தில் நாய்மேல் படும் வெயிலும் அதுவே. மிகுந்த புண்ணியர்களையும் பாவிகளையும் சமமாகக் காக்கும் ஸ்ரீ வேங்கடேஸ்வரனின் நாமம் ஒன்றே.',
      },
    },
    'annamacharya-vinaro-bhagyamu': {
      summary: '“கேளுங்கள் பாக்கியம், விஷ்ணு கதை!” விஷ்ணு கதையே நித்திய கர்மங்களிலுள்ள வேதம்; நாரதர் முதலியோர் தெருத்தெருவாகப் பாடியது; வியாசர் புகழ்ந்தது; சங்கீர்த்தன வடிவில் இருப்பிடம்; இப்போது ஆய்ச்சியர் தயிர் கடையும்போது பரவிய வேங்கடேஸ்வரன் திருநாமம். சுத்த தன்யாசி ராகத்தில் பாடப்படுகிறது.',
      verses: {
        '0.0': 'கேளுங்கள் இந்தப் பாக்கியத்தை, விஷ்ணு கதையை; இதுவே பின்பலம், விஷ்ணு கதை.',
        '1.0': 'தொடக்கத்திலிருந்தே சந்தியாதி கர்மங்களில் வேதமாக இருப்பது விஷ்ணு கதை; நாரதர் முதலியோரால் தெருத்தெருவாக ஒலிப்பது விஷ்ணு கதை.',
        '1.1': 'வேதவியாசர் இடைவிடாது கூறிய புகழ்பெற்ற புனிதமான விஷ்ணு கதை; சங்கீர்த்தனமாக இல்லமான கதை; தேடிய இடமெல்லாம் உள்ளது விஷ்ணு கதை.',
        '1.2': 'ஆய்ச்சியர் ஆர்வத்துடன் மோர் கடைந்தபோது எங்கும் பரவிய விஷ்ணு கதை; இதோ ஸ்ரீ வேங்கடேஸ்வரனின் நாமமான இந்த விஷ்ணு கதை பொங்கி வழிகிறது.',
      },
    },
    'annamacharya-adivo-alladivo': {
      summary: 'திருமலையை அடையும்போது பாடும் பாடல்: “அதோ அதோ ஸ்ரீஹரியின் வாசஸ்தலம்”, ஆயிரம் தலை ஆதிசேஷனின் படங்களால் ஆன மலை, தேவர்களின் உண்மையான இருப்பிடம், நிலத்தில் புதைந்த செல்வம், முக்தியையும் எல்லாச் செல்வங்களையும் தரும் சிகரம். மத்யமாவதி ராகத்தில் பாடப்படுகிறது.',
      verses: {
        '0.0': 'அதோ பாருங்கள், ஸ்ரீஹரியின் இருப்பிடம், பத்தாயிரம் சேஷர்களின் படங்களால் ஆனது.',
        '1.0': 'அதுவே வேங்கடாசலம், அனைத்திலும் உயர்ந்தது; பிரம்மா முதலானோருக்கும் அரிய அதிசயம்; முனிவர்களனைவருக்கும் நித்திய வாசம்; அதைப் பாருங்கள், வணங்குங்கள், ஆனந்தமயம்.',
        '1.1': 'அருகில் அந்த சேஷாசலம்; வானுலகத் தேவர்களின் உண்மையான வாசம்; முன்னால் மூலையில் உள்ள செல்வம்; பொற்சிகரங்களுடன் பிரம்மமயம்.',
        '1.2': 'அந்த வேங்கடமலையே கைவல்ய பதம்; ஸ்ரீ வேங்கடபதியின் செல்வங்கள்; எண்ணினால் எல்லாச் செல்வத்தின் வடிவம் அதுவே; எல்லாப் புனிதங்களுக்கும் புனிதமானது.',
      },
    },
    'annamacharya-kondalalo-nelakonna': {
      summary: 'குன்றுகளில் குடிகொண்ட கோனேட்டி ராயனைப் புகழும் பக்திப் பாடல்: மலையளவு வரங்களை அளிப்பவன், குயவ பக்தர் குறவ நம்பி கேட்ட வரங்களை அளித்தவன், மன்னன் தொண்டைமான் அழைத்த இடத்துக்கு வந்தவன், அனந்தாழ்வானுக்காக மண் சுமந்தவன், திருமலை நம்பியுடன் அன்புடன் பேசியவன், காஞ்சி நம்பியை வரவழைத்தவன். ஹிந்தோள ராகத்தில் பாடப்படுகிறது.',
      verses: {
        '0.0': 'குன்றுகளில் குடிகொண்ட கோனேட்டி ராயன் அவன்; மலையளவு வரங்களை வாரி வழங்குபவன்.',
        '1.0': 'குயவ பக்தர் குறவரதி நம்பி “கொடு” என்று கேட்ட வரங்களெல்லாம் தந்தவன்; போர் செய்த தொண்டைமான் சக்கரவர்த்தி “வா” என்ற இடத்துக்கு வந்து அவனை நம்பியவன்.',
        '1.1': 'உண்மையான மகிழ்ச்சியுடன் அனந்தாழ்வானுக்காக வெட்டி வேலையாக மண் சுமந்தவன்; அன்பு தோன்றத் திருமலை நம்பியுடன் நாள்தோறும் பேசி வருந்தியவன்.',
        '1.2': 'காஞ்சியிலிருந்த திருக்கச்சி நம்பியிடம் கருணைகொண்டு தன்னிடம் வரவழைத்தவன்; கருதி உயர்ந்தவனான வேங்கடேசன் நமக்கு நல்லவனாய்க் கருணையுடன் காப்பவன்.',
      },
    },
    'annamacharya-narayanate-namo-namo': {
      summary: 'நாராயணனுக்கு அவன் பல திருநாமங்களால் வணக்கம்: முரஹர, முகுந்த, மாதவ, கருடகமன, பத்மநாப, நரசிம்ம, ஜலதிசயன, கோபவதூவல்லப; இறுதியில் வேதோத்தர வேங்கடநாயக நாதப்ரிய. மத்யமாவதி ராகத்தில் பாடப்படுகிறது.',
      verses: {
        '0.0': 'நாராயணா, உனக்கு நமோ நமோ; நாரதரால் துதிக்கப்பட்டவனே, நமோ நமோ.',
        '1.0': 'முரஹரா, பவஹரா, முகுந்தா, மாதவா, கருடவாகனா, பங்கஜநாபா; பரம புருஷா, பவபந்த விமோசனா, நரமிருக சரீரா, நமோ நமோ.',
        '1.1': 'கடலில் துயில்பவனே, சூரிய சந்திரர் கண்களாக உடையவனே, தாமரையில் பிறந்தவன் போற்றும் திருவடியிணையே; மகாபலியைக் கட்டியவனே, கோபிகளின் வல்லபனே, நளினோதரனே, உனக்கு நமோ நமோ.',
        '1.2': 'ஆதிதேவா, எல்லா ஆகமங்களாலும் பூஜிக்கப்படுபவனே, யாதவ குல மோகன ரூபா; வேதோத்தாரகா, ஸ்ரீ வேங்கடநாயகா, நாதப்ரியா, உனக்கு நமோ நமோ.',
      },
    },
    'annamacharya-ksheerabdi-kanyakaku': {
      summary: 'பாற்கடலின் மகள் ஸ்ரீ மகாலட்சுமிக்கு நீராஜனப் பாடல்: தாமரை முகம், மார்பு, கூந்தல், கைகள், பாதங்கள், தொடைகள், இடை, நாபி ஆகியவற்றுக்கு ஆரத்தி; இறுதியில் ஸ்ரீ வேங்கடேசனின் பட்டத்தரசி அலமேலுமங்கைக்கு. திருமணங்களிலும் லட்சுமி பூஜையிலும் பாடப்படுகிறது.',
      verses: {
        '0.0': 'பாற்கடலின் கன்னிகைக்கு, ஸ்ரீ மகாலட்சுமிக்கு, தாமரையில் வசிப்பவளுக்கு நீராஜனம்.',
        '1.0': 'தாமரைக்கண்ணியின் முகத்திற்கும் சக்கரவாகப் பறவை போன்ற மார்புக்கும் கற்பூர ஆரத்தி.',
        '1.1': 'வண்டு போன்ற கூந்தல் முடிக்கும் தாமரைக் கரங்களுக்கும் மாணிக்கங்களின் ஆரத்தி.',
        '1.2': 'தளிர் போன்ற பாதங்களுக்கும் வாழைத்தண்டு போன்ற தொடைகளுக்கும் இடையறாத முத்து ஆரத்தி.',
        '1.3': 'அரிய இடைப்பகுதிக்கும் அந்தத் தேவியின் நாபிக்கும் விருப்பத்துடன் பலவண்ண ஆரத்தி.',
        '1.4': 'பகல் முழுதும் ஸ்ரீ வேங்கடேசனின் பட்டத்தரசியாய் விளங்கும் தேவியின் கலைகளுக்கு ஆரத்தி.',
        '1.5': 'உலகில் அலமேலுமங்கையின் எல்லா அழகுகளுக்கும் உண்மையான மங்கள ஆரத்தி.',
      },
    },
    'om-jai-jagdish-hare': {
      summary: 'கிட்டத்தட்ட ஒவ்வொரு பூஜையின் முடிவிலும் பாடப்படும் இந்தியின் மிகப் புகழ்பெற்ற ஆரத்தி: உலகின் தலைவனுக்கு எட்டுச் சிறு பாடல்கள், ஒவ்வொன்றின் பின்னும் பல்லவி “ஓம் ஜெய ஜகதீச ஹரே”. அடியார்களின் துன்பத்தை ஒரு கணத்தில் நீக்குமாறு வேண்டி, அவனைத் தாய் தந்தையாக, ஒரே புகலிடமாக, அகத்துறையும் அறிவாளியாகப் போற்றி, தன் அறியாமையை ஒப்புக்கொண்டு நம்பிக்கையும் பக்தியும் வளர்க்குமாறு கேட்கிறது. பிற்கால அச்சுகளின் இரண்டு கூடுதல் பாடல்கள் இறுதியில் தரப்பட்டுள்ளன.',
      verses: {
        '0.0': 'ஓம், உலகின் தலைவனாகிய ஹரிக்கு வெற்றி; என் தலைவன் ஜகதீச ஹரிக்கு வெற்றி. அடியார்களின் துன்பங்களை, தொண்டர்களின் துன்பங்களை அவன் ஒரு கணத்தில் போக்குகிறான்.',
        '1.0': 'அவனைத் தியானிப்பவர் பயன் பெறுவார்; மனத்தின் துயர் அழியும், இல்லத்துக்கு சுகமும் செல்வமும் வரும், உடலின் துன்பம் மறையும்.',
        '1.1': 'நீயே என் தாயும் தந்தையும்; நான் யாரைச் சரணடைவேன்? உன்னையன்றி வேறு யாரும் இல்லை, யாரிடம் நம்பிக்கை வைப்பேன்?',
        '1.2': 'நீ முழுமையான பரமாத்மா, நீ அகத்துறையும் அறிவாளி; பரப்பிரம்மமே, பரமேசுவரனே, நீ அனைவருக்கும் தலைவன்.',
        '1.3': 'நீ கருணைக் கடல், நீயே காப்பவன்; நான் அறிவிலி, தீயவன், ஆசை நிறைந்தவன்; நான் தொண்டன், நீ தலைவன்: காப்பவனே, அருள் செய்.',
        '1.4': 'நீ ஒருவனே, புலன்களுக்கு எட்டாதவன், அனைவரின் உயிர்த்தலைவன். அருளுடையோனே, மந்தபுத்தியுடைய நான் உன்னை எவ்வாறு அடைவேன்?',
        '1.5': 'எளியவரின் நண்பனே, துயர் தீர்ப்பவனே, நீயே என் தலைவன், என் காவலன். உன் கையை உயர்த்தி என்னை உன் அடைக்கலத்தில் சேர்த்துக்கொள்; நான் உன் வாயிலில் கிடக்கிறேன்.',
        '1.6': 'புலனின்ப ஆசைகளையும் குறைகளையும் அகற்று, தேவனே, பாவங்களைப் போக்கு; நம்பிக்கையையும் பக்தியையும் அடியார் தொண்டையும் வளர்.',
        '2.0': 'ஸ்ரீ ஜகதீசனின் இந்த ஆரத்தியை எவர் பாடுகிறாரோ அவர் சுகமும் செல்வமும் பெறுவார் என்று சிவானந்த சுவாமி கூறுகிறார்.',
        '2.1': 'உடல், மனம், செல்வம், எல்லாம் உன்னுடையவையே; உன்னுடையதையே உனக்கு அர்ப்பணிக்கிறேன், என்னுடையது என்ன இருக்கிறது?',
      },
    },
    'hanuman-ashtak': {
      summary: 'இந்தியில் எட்டுப் பாடல்கள், ஒவ்வொன்றின் முடிவிலும் பல்லவி: “அனுமனே, உன் பெயர் சங்கடமோசன் என்று உலகில் யாருக்குத் தெரியாது?” சூரியனை விழுங்கியது, சுக்ரீவனைக் காத்தது, சீதையைத் தேடியது, இலட்சுமணனுக்காக சஞ்சீவி கொணர்ந்தது, இராம இலட்சுமணரை நாகபாசத்திலிருந்து விடுவித்தது, அகிராவணனைக் கொன்றது ஆகியவற்றை நினைவுகூர்ந்து, எங்கள் துன்பங்கள் அனைத்தையும் போக்குமாறு வேண்டுகிறது. செவ்வாய், சனிக்கிழமைகளில், பெரும்பாலும் அனுமன் சாலீசாவுக்குப் பின் ஓதப்படுகிறது.',
      verses: {
        '0.0': 'குழந்தைப் பருவத்தில் சூரியனை விழுங்கியதால் மூவுலகும் இருண்டது; உலகம் அஞ்சியது, இத்துன்பத்தை யாராலும் நீக்க இயலவில்லை. தேவர்கள் வந்து வேண்டியபோது சூரியனை விட்டுத் துயர் தீர்த்தீர். அனுமனே, உன் பெயர் சங்கடமோசன் என்று உலகில் யாருக்குத் தெரியாது?',
        '0.1': 'வாலியின் அச்சத்தால் சுக்ரீவன் மலையில் வசித்து பெருமானின் வருகைக்காக வழி பார்த்திருந்தான். மகாமுனிவர் திடுக்கிட்டு சாபமிட்டிருந்தார்; என்ன நினைப்பது? நீ அந்தணர் உருவில் பெருமானை அழைத்து வந்து உன் தொண்டனின் துயரைப் போக்கினாய். அனுமனே, உன் பெயர் சங்கடமோசன் என்று உலகில் யாருக்குத் தெரியாது?',
        '0.2': 'அங்கதனுடன் சீதையைத் தேடச் சென்றவர்களிடம் சுக்ரீவன்: “செய்தி கொண்டுவராமல் இங்கு வந்தால் பிழைக்கமாட்டீர்கள்” என்றான். கடற்கரையில் தேடித் தேடி அனைவரும் சோர்ந்தனர்; அப்போது நீ சீதையின் செய்தி கொணர்ந்து உயிர் காத்தாய். அனுமனே, உன் பெயர் சங்கடமோசன் என்று உலகில் யாருக்குத் தெரியாது?',
        '0.3': 'இராவணன் அரக்கியரைக் கொண்டு சீதையை வதைத்தான்; அப்போது நீ சென்று பெரிய அரக்கர்களைக் கொன்றாய். சீதை அசோக மரத்திடம் தீ கேட்டபோது பிரபுவின் மோதிரத்தைத் தந்து அவள் துயரைத் துடைத்தாய். அனுமனே, உன் பெயர் சங்கடமோசன் என்று உலகில் யாருக்குத் தெரியாது?',
        '0.4': 'இராவணன் மகனின் அம்பு இலட்சுமணனின் மார்பில் தைத்து அவன் உயிர் நீங்கியபோது, நீ வைத்தியர் சுஷேணனை வீட்டோடு கொண்டு வந்து துரோண மலையைப் பெயர்த்தாய்; சஞ்சீவியைக் கொணர்ந்து கையில் தந்து இலட்சுமணன் உயிரைக் காத்தாய். அனுமனே, உன் பெயர் சங்கடமோசன் என்று உலகில் யாருக்குத் தெரியாது?',
        '0.5': 'அப்போது இராவணன் மறைந்து போரிட்டு எல்லார் தலையிலும் நாகபாசம் இட்டான்; இராமனுடன் சேனை முழுவதும் மயக்கமடைந்தது, இது பெரும் துன்பம். அனுமனே, நீ பறவையரசன் கருடனை அழைத்து வந்து பந்தம் அறுத்து பெருங்கலக்கத்தை நீக்கினாய். உன் பெயர் சங்கடமோசன் என்று உலகில் யாருக்குத் தெரியாது?',
        '0.6': 'அகிராவணன் சகோதரனுடன் இராமனைப் பாதாளத்துக்குக் கொண்டு சென்று தேவிக்குப் பலியிட அனைவரும் கூடி ஆலோசித்தபோது, நீ உதவிக்குச் சென்று அகிராவணனைப் படையுடன் அழித்தாய். அனுமனே, உன் பெயர் சங்கடமோசன் என்று உலகில் யாருக்குத் தெரியாது?',
        '0.7': 'தேவர்களுக்குப் பெரும் காரியங்களைச் செய்தீர்; வீர மகாபிரபுவே, எண்ணிப் பாருங்கள்: ஏழையாகிய என் எந்தத் துன்பம் உம்மால் போக்க இயலாதது? அனுமனே, எங்களுக்கு எந்தத் துன்பம் இருந்தாலும் விரைவில் போக்குங்கள். உன் பெயர் சங்கடமோசன் என்று உலகில் யாருக்குத் தெரியாது?',
        '1.0': 'சிவந்த உடல், செம்மையில் ஒளிரும், செந்நிற வாலுடன், வஜ்ர உடலுடன் அசுரர்களை அழிக்கும் வீர வானரனுக்கு வெற்றி வெற்றி வெற்றி.',
      },
    },
    'shiv-chalisa': {
      summary: 'இந்தியில் சிவனைப் போற்றும் நாற்பது சௌபாய் பாடல்: பிறை, கங்கை, நாககுண்டலம், திரிசூலம் கொண்ட வடிவம்; தாரகன், ஜலந்தரன், திரிபுரம் ஆகியவற்றிலிருந்து தேவர்களைக் காத்தது, பாற்கடல் கடைந்த நஞ்சு; இலங்கைக்கு முன் இராமன் செய்த பூஜை; துன்பத்தில் உதவி கோரல்; திரயோதசியில் ஓதும் பலன். திங்கள்கிழமைகளிலும் ஸ்ராவண மாதத்திலும் ஓதப்படுகிறது.',
      verses: {
        '0.0': 'கிரிஜையின் மகனும் மங்கலத்தின் மூலமும் ஞானியுமான கணேசனுக்கு வெற்றி; அயோத்தியாதாசர் கூறுகிறார்: அபய வரத்தை அருள்க.',
        '1.0': 'கிரிஜாபதியே, ஏழைகளிடம் இரங்குபவனே, எப்போதும் சான்றோரைக் காப்பவனே, வெற்றி உமக்கு.',
        '1.1': 'உங்கள் நெற்றியில் பிறை அழகாக விளங்குகிறது; காதுகளில் நாகப்படக் குண்டலங்கள்.',
        '1.2': 'உமது உடல் வெண்மை, தலையிலிருந்து கங்கை பாய்கிறாள்; மண்டை ஓட்டு மாலை அணிந்து, உடலில் திருநீறு பூசியுள்ளீர்.',
        '1.3': 'உமது ஆடை புலித்தோல்; அந்த அழகைக் கண்டு நாகங்களும் மயங்குகின்றன.',
        '1.4': 'மைனாவின் செல்ல மகளான பார்வதி உமது இடப்பாகத்தில் ஒப்பற்ற அழகுடன் திகழ்கிறாள்.',
        '1.5': 'கையிலுள்ள திரிசூலம் மிகவும் அழகாகத் திகழ்ந்து எப்போதும் பகைவரை அழிக்கிறது.',
        '1.6': 'நந்தியும் கணேசனும் அங்கே கடல் நடுவே மலர்ந்த தாமரைகள் போல் அழகாக இருக்கிறார்கள்.',
        '1.7': 'கார்த்திகேயன், கருமை நிறத்தவர், கணங்களின் தலைவர்; இந்த அழகை யாராலும் சொல்ல இயலாது.',
        '1.8': 'தேவர்கள் எப்போது சென்று அழைத்தாலும் அப்போதே அவர்கள் துன்பத்தை நீக்கினீர்.',
        '1.9': 'தாரகன் பெரும் தொல்லை செய்தபோது தேவர்கள் அனைவரும் சேர்ந்து உம்மைப் போற்றினர்.',
        '1.10': 'உடனே ஆறுமுகனை அனுப்பினீர்; அவர் கண்ணிமைக்கும் நேரத்தில் அவனை அழித்தார்.',
        '1.11': 'ஜலந்தர அசுரனை நீரே அழித்தீர்; உமது நற்புகழ் உலகறிந்தது.',
        '1.12': 'திரிபுராசுரன் போர் செய்தபோது கருணையால் அனைவரையும் காத்தீர்.',
        '1.13': 'பகீரதன் பெரும் தவம் செய்தான்; புராரியே, அவனுக்குச் செய்த முந்திய உறுதிமொழியை நிறைவேற்றினீர்.',
        '1.14': 'கொடையாளிகளில் உமக்கு நிகர் யாருமில்லை; அடியார்கள் எப்போதும் உம்மைத் துதிக்கின்றனர்.',
        '1.15': 'வேதங்கள் உமது திருநாமப் பெருமையைப் பாடுகின்றன; நீர் சொல்லொணாதவர், ஆதியற்றவர்; உமது இரகசியத்தை எவரும் அறியவில்லை.',
        '1.16': 'பாற்கடல் கடைந்தபோது நஞ்சுத் தீ எழுந்து தேவரும் அசுரரும் எரிந்து தவித்தனர்.',
        '1.17': 'அங்கே இரங்கி உதவினீர்; அதிலிருந்து நீலகண்டன் என்ற பெயர் வந்தது.',
        '1.18': 'இராமச்சந்திரன் உம்மை வழிபட்டு இலங்கையை வென்று விபீஷணனுக்கு அளித்தபோது,',
        '1.19': 'அவன் ஆயிரம் தாமரைகளை அர்ப்பணித்துக்கொண்டிருந்தபோது புராரியே, நீர் அவனைச் சோதித்தீர்.',
        '1.20': 'ஒரு தாமரையை மறைத்தீர்; தாமரைக்கண்ணன் தன் கண்ணாலேயே பூஜிக்க நினைத்தான்.',
        '1.21': 'அவனது கடும் பக்தியைக் கண்டு சங்கரன் மகிழ்ந்து விரும்பிய வரம் தந்தான்.',
        '1.22': 'வெற்றி வெற்றி வெற்றி, அனந்தனே, அழிவற்றவனே, எல்லோர் இதயத்திலும் உறைந்து அருள்பவனே.',
        '1.23': 'தீயவர் அனைவரும் தினமும் என்னை வருத்துகிறார்கள்; அலைந்து திரிகிறேன், எனக்கு அமைதி இல்லை.',
        '1.24': 'காப்பாற்றுங்கள் காப்பாற்றுங்கள் நாதனே, அழைக்கிறேன்; இந்த நேரத்தில் வந்து என்னை மீட்டருளுங்கள்.',
        '1.25': 'திரிசூலத்தை ஏந்தி என் பகைவரை அழியுங்கள்; இந்தத் துன்பத்திலிருந்து என்னை மீட்டருளுங்கள்.',
        '1.26': 'தாய், தந்தை, சகோதரர் எல்லோரும் உள்ளனர்; ஆனால் துன்பத்தில் யாரும் விசாரிப்பதில்லை.',
        '1.27': 'சுவாமி, எனக்கு ஒரே நம்பிக்கை நீங்கள்தான்; வந்து என் பெரும் துன்பத்தைப் போக்குங்கள்.',
        '1.28': 'ஏழைகளுக்கு எப்போதும் செல்வம் தருகிறீர்; யார் வேண்டினாலும் பலன் பெறுவர்.',
        '1.29': 'உம்மை எவ்வாறு துதிப்பேன்? நாதனே, இப்போது என் பிழையை மன்னியுங்கள்.',
        '1.30': 'சங்கரா, துன்பங்களை அழிப்பவனே, மங்கலத்திற்குக் காரணனே, இடையூறுகளை நீக்குபவனே.',
        '1.31': 'யோகிகள், துறவிகள், முனிவர்கள் உம்மைத் தியானிக்கிறார்கள்; சாரதையும் நாரதரும் உம்மை வணங்குகிறார்கள்.',
        '1.32': 'நமோ நமோ, ஜய நமஃ சிவாய; பிரம்மா முதலிய தேவரும் உமது எல்லையை அறியார்.',
        '1.33': 'யார் மனமுவந்து இதை ஓதுகிறாரோ அவருக்குச் சம்புவின் துணை கிடைக்கும்.',
        '1.34': 'கடனில் உள்ளவர் இதை ஓதினால் கடனிலிருந்து விடுபடுவார்.',
        '1.35': 'மகன் வேண்டுபவருக்கு நிச்சயம் சிவனின் அருள் கிட்டும்.',
        '1.36': 'திரயோதசியில் புரோகிதரை அழைத்து கவனத்துடன் ஹோமம் செய்யச் செய்யவேண்டும்.',
        '1.37': 'எப்போதும் திரயோதசி விரதம் இருப்பவர் உடலில் துன்பம் இராது.',
        '1.38': 'தூபம், தீபம், நைவேத்தியம் படைத்து சங்கரன் முன் இதை ஓத வேண்டும்.',
        '1.39': 'பிறவிதோறும் செய்த பாவங்கள் அழிந்து இறுதியில் சிவபுரத்தில் இடம் கிடைக்கும்.',
        '1.40': 'அயோத்தியாதாசர் கூறுகிறார்: என் நம்பிக்கை உம்மிடமே; என் துன்பங்கள் அனைத்தையும் அறிந்து போக்குங்கள்.',
        '2.0': 'தினமும் காலையில் நியமமாக இந்த சாலீசாவை ஓதுகிறேன்; ஜகதீசா, என் விருப்பங்களை நிறைவேற்றுங்கள்.',
        '2.1': 'ஹேமந்த காலத்தில் மார்கழி ஷஷ்டியன்று, சம்வத் அறுபத்து நான்கில், சிவ ஸ்துதியான இந்த சாலீசா அனைவரின் நன்மைக்காக நிறைவுற்றது.',
      },
    },
    'durga-chalisa': {
      summary: 'அன்னையைப் போற்றும் நாற்பது சௌபாய் இந்திப் பாடல்: அவளது ஒளிமிக்க வடிவம், சரஸ்வதி, நரசிம்ம சக்தி, லட்சுமி, அன்னபூரணி, காளி, தசமகா வித்யைகளின் வடிவங்கள், சும்பன் நிசும்பன் ரக்தபீஜன் மகிஷாசுரன் வதம், சங்கராசாரியரின் மனவருத்தம், அன்புடன் பாடுவோருக்கு உறுதி. செவ்வாய், வெள்ளி, நவராத்திரியில் ஓதப்படுகிறது.',
      verses: {
        '0.0': 'இன்பம் தரும் துர்க்கைக்கு நமோ நமோ; துன்பம் போக்கும் துர்க்கைக்கு நமோ நமோ.',
        '0.1': 'உமது ஒளி உருவற்றது; அதன் வெளிச்சம் மூவுலகிலும் பரவியுள்ளது.',
        '0.2': 'நெற்றியில் பிறை, மிக அகன்ற முகம், சிவந்த கண்கள், கடுமையான புருவங்கள்.',
        '0.3': 'அன்னையின் உருவம் மிகவும் அழகானது; தரிசிப்பவர்கள் பெரும் இன்பம் பெறுகிறார்கள்.',
        '0.4': 'உலகின் சக்தியைப் படைத்து, காக்க உணவையும் செல்வத்தையும் தந்தீர்.',
        '0.5': 'அன்னபூரணியாக உலகைக் காத்தீர்; நீரே ஆதி அழகிய கன்னி.',
        '0.6': 'பிரளய காலத்தில் எல்லாவற்றையும் அழிப்பவள் நீ; நீ கௌரி, சிவ சங்கரனின் அன்புக்குரியவள்.',
        '0.7': 'சிவனும் யோகிகளும் உமது குணங்களைப் பாடுகிறார்கள்; பிரம்மாவும் விஷ்ணுவும் நித்தம் உம்மைத் தியானிக்கிறார்கள்.',
        '0.8': 'சரஸ்வதி வடிவம் எடுத்து நல்லறிவு தந்து முனிவர்களைக் காத்தீர்.',
        '0.9': 'அம்மா, நரசிம்ம வடிவம் தாங்கி தூணைப் பிளந்து தோன்றினீர்.',
        '0.10': 'பிரகலாதனைக் காத்து இரண்யாட்சனை (இரண்யகசிபுவை) சொர்க்கத்துக்கு அனுப்பினீர்.',
        '0.11': 'உலகில் லட்சுமி வடிவம் ஏற்று ஸ்ரீ நாராயணனின் திருமேனியில் இணைந்தீர்.',
        '0.12': 'பாற்கடலில் விளையாடுகிறீர்; கருணைக்கடலே, என் ஆசையை நிறைவேற்றுங்கள்.',
        '0.13': 'ஹிங்குலாஜில் நீரே பவானி; உமது அளவற்ற பெருமையைச் சொல்ல முடியாது.',
        '0.14': 'மாதங்கி, தூமாவதி, புவனேஸ்வரி, பகளா: நீரே இன்பம் தருபவள்.',
        '0.15': 'ஸ்ரீ பைரவி, உலகைக் கடத்தும் தாரா, பிறவித் துயர் நீக்கும் சின்னமஸ்தா.',
        '0.16': 'சிங்கம் உமது வாகனம், பவானி; வீர லாங்குரன் முன்னே வழிகாட்டி நடக்கிறான்.',
        '0.17': 'கையில் கபாலமும் வாளும் ஒளிர்கின்றன; அவற்றைக் கண்டு காலனும் அஞ்சி ஓடுகிறான்.',
        '0.18': 'ஆயுதங்களும் திரிசூலமும் அழகு செய்கின்றன; அவற்றால் பகைவர் மனத்தில் வலி எழுகிறது.',
        '0.19': 'நகர்கோட்டில் நீர் வீற்றிருக்கிறீர்; மூவுலகிலும் உமது முரசு ஒலிக்கிறது.',
        '0.20': 'சும்ப, நிசும்ப அசுரர்களைக் கொன்றீர்; ரக்தபீஜனையும் சங்கர்களையும் அழித்தீர்.',
        '0.21': 'மகிஷாசுரன் மிகவும் செருக்கு கொண்டவன்; அவன் பாவச்சுமையால் பூமி தவித்தது.',
        '0.22': 'பயங்கரமான காளிகா வடிவம் ஏற்று அவனை சேனையுடன் அழித்தீர்.',
        '0.23': 'சான்றோர்மேல் கடுந்துயர் வந்தபோதெல்லாம் அம்மா, நீர் அப்போதெல்லாம் துணை நின்றீர்.',
        '0.24': 'அமராவதியிலும் மற்ற உலகங்களிலும் உமது பெருமையால் எல்லோரும் துன்பமின்றி இருக்கிறார்கள்.',
        '0.25': 'ஜ்வாலாவில் (ஜ்வாலாமுகி) உமது ஜோதி உள்ளது; ஆடவரும் பெண்டிரும் எப்போதும் உம்மை வழிபடுகின்றனர்.',
        '0.26': 'அன்பும் பக்தியுமாக உமது புகழைப் பாடுபவரிடம் துன்பமும் வறுமையும் நெருங்குவதில்லை.',
        '0.27': 'மனம் ஒன்றி உம்மைத் தியானிப்பவருக்குப் பிறப்பு இறப்பு நீங்கும்.',
        '0.28': 'யோகிகள், தேவர், முனிவர் உரக்கக் கூறுகிறார்கள்: உமது சக்தியின்றி யோகம் இல்லை.',
        '0.29': 'சங்கராசாரியார் தவம் செய்து காமத்தையும் கோபத்தையும் வென்றார்.',
        '0.30': 'இரவும் பகலும் சங்கரனைத் தியானித்தார்; எப்போதும் உம்மை நினைக்கவில்லை.',
        '0.31': 'சக்தியின் இரகசியத்தை அறியவில்லை; சக்தி நீங்கியபோது மனம் வருந்தினார்.',
        '0.32': 'சரணடைந்து உமது புகழைப் போற்றினார்: வெற்றி வெற்றி வெற்றி ஜகதம்பா பவானி.',
        '0.33': 'ஆதி ஜகதம்பா மகிழ்ந்து தாமதமின்றிச் சக்தியை அளித்தாள்.',
        '0.34': 'அம்மா, பெருந்துயர் என்னைச் சூழ்ந்துள்ளது; நீரன்றி என் துயரை யார் போக்குவர்?',
        '0.35': 'ஆசையும் தாகமும் என்னை மிகவும் வருத்துகின்றன; மூடப் பகைவர் என்னை அச்சுறுத்துகின்றனர்.',
        '0.36': 'மகாராணியே, என் பகைவர்களை அழியுங்கள்; பவானி, ஒருமனத்துடன் உம்மை நினைக்கிறேன்.',
        '0.37': 'கருணைமிகு அன்னையே, அருள்க; ரித்தி சித்திகளை அளித்து என்னை மகிழ்விப்பீர்.',
        '0.38': 'நான் உயிரோடிருக்கும் வரை உமது அருளைப் பெற்று, உமது புகழை எப்போதும் சொல்வேன்.',
        '0.39': 'துர்க்கா சாலீசாவைப் பாடுபவர் எல்லா இன்பங்களையும் அனுபவித்து பரமபதம் அடைவார்.',
        '0.40': 'தேவிதாசன் உம் சரணம் புகுந்தவன் என்று அறிந்து அருள்க, ஜகதம்பா பவானி.',
        '1.0': 'சரணடைந்தவர் காக்கப்பட்டால் பக்தர் அச்சமின்றி இருப்பார்; உம் சரணம் வந்துள்ளேன், அன்னையே, என்னை மடியில் ஏற்றுக்கொள்ளுங்கள்.',
      },
    },
    'bajrang-baan': {
      summary: 'அச்சம், துன்பங்களுக்கு எதிராக விடப்படும் “அம்பு” போல அனுமனிடம் இந்தியில் செய்யும் உருக்கமான பிரார்த்தனை: அவனது கடல் தாண்டுதல், சுரசை, லங்கிணியுடன் சந்திப்பு, இலங்கை எரிப்பு, இலட்சுமணனைக் காத்தது ஆகியவற்றை நினைவூட்டி, இராமன் பெயரால் உடனே வந்து பேய்களையும் பகைவரையும் துயரையும் ஓட்டவேண்டும் என்று கேட்கிறது. நம்பிக்கையுடன் ஓதுவோருக்கு உறுதியளித்து முடிகிறது.',
      verses: {
        '0.0': 'உறுதியான அன்பும் நம்பிக்கையுமாக பணிவுடன் தொழுபவரின் எல்லாக் காரியங்களையும் அனுமன் நன்றாக முடித்துத் தருவான்.',
        '1.0': 'சான்றோரின் நலம் நாடும் அனுமனுக்கு வெற்றி; பிரபுவே, எங்கள் விண்ணப்பத்தைக் கேளுங்கள்.',
        '1.1': 'அடியார் காரியத்தில் தாமதிக்க வேண்டாம்; ஓடிவந்து பெருமகிழ்ச்சி அளியுங்கள்.',
        '1.2': 'கடலைத் தாண்டியதுபோல, விரிந்த சுரசையின் வாயில் புகுந்ததுபோல,',
        '1.3': 'முன்சென்று லங்கிணி தடுத்தபோது உதைத்து அவளை தேவலோகம் சேர்த்ததுபோல,',
        '1.4': 'சென்று விபீஷணனுக்கு இன்பமளித்து, சீதையைக் கண்டு பேரின்பம் அடைந்ததுபோல,',
        '1.5': 'தோட்டத்தை அழித்துக் கடலில் மூழ்கடித்து, மிகுந்த விரைவில் எமனையும் நடுங்கச் செய்ததுபோல,',
        '1.6': 'அட்சயகுமாரனைக் கொன்று, வாலைச் சுற்றி இலங்கையை எரித்ததுபோல,',
        '1.7': 'இலங்கை அரக்கு போல எரிந்தது; தேவருலகில் வெற்றி முழக்கம் எழுந்தது,',
        '1.8': 'இப்போது ஸ்வாமி, தாமதம் ஏன்? அந்தர்யாமியே, அருள்புரியுங்கள்.',
        '1.9': 'இலட்சுமணனுக்கு உயிர் தந்தவனுக்கு வெற்றி வெற்றி; விரைந்து என் துன்பத்தை முடிவுக்குக் கொண்டுவாருங்கள்.',
        '1.10': 'மலையைத் தாங்கியவனுக்கு வெற்றி; இன்பக் கடலுக்கு வெற்றி; தேவர் கூட்டத்தின் திறன்மிக்க வீரனுக்கு வெற்றி.',
        '1.11': 'ஓம் ஹனு ஹனு ஹனு அனுமனே, உறுதியுடையவனே; பகைவரை வஜ்ர ஆணிகளால் அடியுங்கள்.',
        '1.12': 'கதையும் வஜ்ரமும் ஏந்திப் பகைவரைக் கொல்லுங்கள்; மகாராஜா, உங்கள் அடியேனை மீட்டருளுங்கள்.',
        '1.13': 'ஓங்கார ஹுங்கார மகாபிரபுவே, ஓடிவாருங்கள்; வஜ்ரமும் கதையுமாக தாமதிக்க வேண்டாம்.',
        '1.14': 'ஓம் ஹ்ரீம் ஹ்ரீம் ஹ்ரீம் வானரத் தலைவா; ஓம் ஹும் ஹும் ஹும், பகைவனின் மார்பிலும் தலையிலும் அடி.',
        '1.15': 'ஹரியின் ஆணைப்படி உண்மையாகட்டும்; இராமதூதனே, ஓடிச்சென்று கொல்லுங்கள்.',
        '1.16': 'ஆழங்காண இயலாத அனுமனுக்கு வெற்றி வெற்றி வெற்றி; அடியவன் எந்தக் குற்றத்தால் துன்புறுகிறான்?',
        '1.17': 'பூஜை, ஜபம், தவம், நியமம், ஆசாரம்: உம் அடியேனுக்கு ஒன்றும் தெரியாது.',
        '1.18': 'காடு, தோட்டம், பாதை, மலை, வீடு எங்கிருந்தாலும் உமது வலிமையால் நாங்கள் அஞ்சுவதில்லை.',
        '1.19': 'கைகூப்பி உமது பாதங்களில் விழுகிறேன்; இந்த நேரத்தில் வேறு யாரை அழைப்பேன்?',
        '1.20': 'அஞ்சனை மகனே, வலிமையானவனே, சங்கர சுதனே, தீரனான அனுமனுக்கு வெற்றி.',
        '1.21': 'கடுமையான முகம் உடையவனே, காலனின் குலத்தை அழிப்பவனே, இராமனின் துணையுடன் எப்போதும் காப்பவனே.',
        '1.22': 'பூதம், பிரேதம், பிசாசு, இரவுலாவி, நெருப்பு, வேதாளம், காலன், கொள்ளைநோய்:',
        '1.23': 'இவர்களை அழியுங்கள், இராமன் ஆணை; நாதனே, உமது பெயரின் மரியாதையைக் காப்பாற்றுங்கள்.',
        '1.24': 'ஜானகி உங்களை ஹரியின் தொண்டன் என்றாள்; அவள் ஆணை, தாமதிக்க வேண்டாம்.',
        '1.25': 'வானத்தில் வெற்றி முழக்கம் ஒலிக்கிறது; நினைத்தவுடன் தாங்கமுடியாத துன்பம் அழியும்.',
        '1.26': 'உமது திருவடியைச் சரணடைந்து கைகூப்பி வேண்டுகிறேன்; இந்த நேரத்தில் வேறு யாரை அழைப்பேன்?',
        '1.27': 'எழுங்கள் எழுங்கள், புறப்படுங்கள்; இராமன் ஆணை; கைகூப்பி உங்கள் பாதங்களில் விழுகிறேன்.',
        '1.28': 'ஓம் சம் சம் சம் சம் வேகமாகச் செல்பவனே; ஓம் ஹனு ஹனு ஹனு அனுமனே.',
        '1.29': 'ஓம் ஹம் ஹம் அலைபாயும் குரங்கு முழங்குகிறது; ஓம் சம் சம் தீயோர் படை அஞ்சி ஓடுகிறது.',
        '1.30': 'உம்முடையவர்களை உடனே காப்பாற்றுங்கள்; நினைத்தவுடன் எங்களுக்கு மகிழ்ச்சி.',
        '1.31': 'இந்த பஜ்ரங் பாணம் யாரைத் தாக்குகிறதோ, அவனை யார் காப்பாற்ற முடியும்?',
        '1.32': 'பஜ்ரங் பாணத்தை ஓதுபவரின் உயிரை அனுமன் காக்கிறான்.',
        '1.33': 'இந்த பஜ்ரங் பாணத்தை ஜபிப்பவரைக் கண்டு பூத பிரேதங்கள் எல்லாம் நடுங்கும்.',
        '1.34': 'தூபமிட்டு எப்போதும் ஜபிப்பவரின் உடலில் துன்பம் இராது.',
        '2.0': 'உறுதியான அன்புடன் வானரத் தலைவனை வழிபட்டு எப்போதும் இதயத்தில் தியானம் வைப்பவரின் எல்லாக் காரியங்களும் நன்மையாக அனுமனால் நிறைவேறும்.',
      },
    },
    'ganesh-aarti': {
      summary: 'கிட்டத்தட்ட ஒவ்வொரு பூஜையின் தொடக்கத்திலும் விநாயகர் சதுர்த்தியிலும் பாடப்படும் இந்தி கணேச ஆரத்தி. ஒற்றைத் தந்தமும் நான்கு கைகளும் நெற்றியில் குங்குமமும் உடைய, எலியில் வரும் தேவனைப் புகழ்ந்து, வெற்றிலை, பழம், கொட்டைகள், லட்டுகள் படைப்பதைக் கூறி, அவன் பார்வையற்றோருக்குக் கண்ணும் நோயாளிக்கு உடல்நலமும் மகப்பேறற்றோருக்குக் குழந்தையும் ஏழைக்குச் செல்வமும் தருகிறான் என்கிறது.',
      verses: {
        '0.0': 'கணேசனுக்கு வெற்றி, கணேசனுக்கு வெற்றி, தேவன் கணேசனுக்கு வெற்றி; அவனுக்குத் தாய் பார்வதி, தந்தை மகாதேவன்.',
        '1.0': 'ஒற்றைத் தந்தமுடையவன், அருளாளன், நான்கு கைகளை உடையவன்; நெற்றியில் குங்குமம் விளங்குகிறது, எலியே அவன் வாகனம்.',
        '1.1': 'வெற்றிலை படைக்கப்படுகிறது, பழம் படைக்கப்படுகிறது, கொட்டைகளும் படைக்கப்படுகின்றன; லட்டுகள் நைவேத்தியமாகின்றன, அடியார்கள் தொண்டு செய்கிறார்கள்.',
        '1.2': 'அவன் பார்வையற்றவருக்குக் கண்களும், தொழுநோயாளருக்கு நலமான உடலும், மகப்பேறற்றவருக்குக் குழந்தையும், ஏழைக்குச் செல்வமும் தருகிறான்.',
        '1.3': '‘சூர்’ ஷ்யாம் உன் அடைக்கலம் புகுந்தான்; அவன் தொண்டை பலனுள்ளதாக்கு. அவனுக்குத் தாய் பார்வதி, தந்தை மகாதேவன்.',
        '2.0': 'எளியவரின் மானத்தைக் காப்பாய், சம்புவின் மகனே; ஆசைகளை நிறைவேற்று, உனக்கே என்னை அர்ப்பணிக்கிறேன்.',
      },
    },
    'lakshmi-aarti': {
      summary: 'வெள்ளிக்கிழமையிலும் தீபாவளி இலட்சுமி பூஜையிலும் பாடப்படும் இந்தி இலட்சுமி ஆரத்தி. விஷ்ணுவும் பிரம்மாவும் இரவும் பகலும் வழிபடும் அன்னையை வரவேற்று, உமா, ரமா, பிராம்மணியாகப் போற்றி; சுகமும் செல்வமும் தருபவள், பாற்கடலில் தோன்றியவள், அவளின்றி வேள்வி, ஆடை, உணவு, பதினான்கு ரத்தினங்கள் எதுவும் இல்லை என்று கூறி, பாடுவோருக்கு மகிழ்ச்சியும் பாவ விடுதலையும் உறுதியளிக்கிறது.',
      verses: {
        '0.0': 'ஓம், அன்னை இலட்சுமிக்கு வெற்றி, அம்மா இலட்சுமிக்கு வெற்றி; உன்னை இரவும் பகலும் ஹரி, விஷ்ணு, படைப்பாளன் பிரம்மா வழிபடுகிறார்கள்.',
        '1.0': 'உமா, ரமா, பிராம்மணியாக நீயே உலகின் அன்னை; சூரியனும் சந்திரனும் உன்னைத் தியானிக்கிறார்கள், நாரத முனிவர் உன்னைப் பாடுகிறார்.',
        '1.1': 'துர்க்கை வடிவில் களங்கமற்றவளே, சுகமும் செல்வமும் தருபவளே; உன்னைத் தியானிப்பவர் செழிப்பும் சித்திகளும் செல்வமும் பெறுகிறார்.',
        '1.2': 'நீ பாதாளத்திலும் வாழ்பவள், நீயே நன்மை தருபவள்; வினையின் ஆற்றலை ஒளிரச் செய்பவள், பிறவிக் கடலிலிருந்து காப்பவள்.',
        '1.3': 'நீ எந்த வீட்டில் வசிக்கிறாயோ அங்கே நற்குணங்கள் அனைத்தும் வருகின்றன; எல்லாம் இயலுவதாகிறது, மனம் அஞ்சுவதில்லை.',
        '1.4': 'நீயின்றி வேள்விகள் நடப்பதில்லை, யாருக்கும் ஆடை கிடைப்பதில்லை; உணவு பானங்களின் செழிப்பு அனைத்தும் உன்னிடமிருந்தே வருகிறது.',
        '1.5': 'நற்குணங்களின் அழகிய கோயிலே, பாற்கடலில் தோன்றியவளே; நீயின்றி பதினான்கு ரத்தினங்களை யாரும் பெறுவதில்லை.',
        '1.6': 'மகாலட்சுமியின் இந்த ஆரத்தியைப் பாடுபவரின் உள்ளத்தில் மகிழ்ச்சி நிறைகிறது, பாவம் நீங்குகிறது.',
      },
    },
    'shiv-aarti': {
      summary: 'திங்கள், பிரதோஷம், மகாசிவராத்திரி நாட்களில் பாடப்படும் சிவனின் இந்தி ஆரத்தி. அவனை ஓங்காரமாகவும் பிரம்மா விஷ்ணு சதாசிவன் ஆகியோரின் ஒருமையாகவும் வரவேற்று, அவனது ஒன்று, நான்கு, ஐந்து முகங்கள், உருத்திராட்சம், மண்டையோட்டு மாலை, புலித்தோல், திரிசூலம், பிறைநிலவு ஆகியவற்றை வருணித்து, சடையிலுள்ள கங்கை, கயிலாயம், காசி, பாடுவோருக்கான பலன் என்பவற்றுடன் முடிகிறது. பல பதிப்புகளில் சேர்க்கும் நான்கு பாடல்கள் தனிப் பிரிவில் உள்ளன.',
      verses: {
        '0.0': 'ஓம், ஓங்கார வடிவான சிவனுக்கு வெற்றி; என் தலைவன் ஓங்கார சிவனுக்கு வெற்றி. பிரம்மா, விஷ்ணு, சதாசிவன்; தன் துணைவியை உடலின் பாதியாகத் தாங்குபவன்.',
        '1.0': 'ஒரு முகம், நான்கு முகம், ஐந்து முகங்களுடன் விளங்குகிறான்; அன்னம், கருடன், காளை வாகனங்களில் அழகுறுகிறான்.',
        '1.1': 'இரண்டு கை, நான்கு கை, பத்துக் கைகளுடன் மிக அழகாக விளங்குகிறான்; முக்குண வடிவைக் கண்டு மூவுலக மக்களும் மயங்குகிறார்கள்.',
        '1.2': 'உருத்திராட்ச மாலை, வனமாலை, மண்டையோட்டு மாலை அணிந்தவன்; சந்தனமும் கஸ்தூரியும் விளங்குகின்றன, நெற்றியில் பிறையைச் சூடியவன்.',
        '1.3': 'வெண்ணாடை, மஞ்சள் ஆடை, உடலில் புலித்தோல்; சனகாதி முனிவர், கருடன் முதலியோர், பூதகணங்கள் அவனுடன் உள்ளனர்.',
        '1.4': 'கைகளில் கமண்டலம், சக்கரம், திரிசூலம் ஏந்தியவன்; சுகம் தருபவன், துயர் தீர்ப்பவன், உலகைக் காப்பவன்.',
        '1.5': 'பிரம்மா, விஷ்ணு, சதாசிவனை வேறுபட்டவர் என்று எண்ணுவது அறிவின்மை; பிரணவ எழுத்தாகிய ஓம் என்பதில் இம்மூவரும் ஒன்றாக விளங்குகின்றனர்.',
        '2.0': 'இலட்சுமி, சாவித்திரி, பார்வதி அவனுடன் உள்ளனர்; பார்வதி அவனது பாதி உடல், சிவனின் சடையிலிருந்து கங்கை பாய்கிறாள்.',
        '2.1': 'மலைகள் பார்வதிக்கு அழகு சேர்க்கின்றன, சங்கரன் கயிலாயத்தில் உறைகிறான்; கஞ்சாவும் ஊமத்தையும் அவன் உணவு, சாம்பலில் அவன் வாசம்.',
        '2.2': 'சடையில் கங்கை பாய்கிறாள், கழுத்தில் மண்டையோட்டு மாலை; ஆதிசேடன் சுற்றிக்கொண்டிருக்கிறான், மான்தோலைப் போர்த்தியிருக்கிறான்.',
        '2.3': 'காசியில் விஸ்வநாதனாக எழுந்தருளியுள்ளான், பிரம்மச்சாரி நந்தியுடன்; நாள்தோறும் எழுந்து தரிசனம் பெறுகிறார்கள், அவன் மகிமை மிகப் பெரியது.',
        '3.0': 'முக்குணங்களின் தலைவனின் இந்த ஆரத்தியை எவர் பாடுகிறாரோ அவர் சுகமும் செல்வமும் பெறுவார் என்று சிவானந்த சுவாமி கூறுகிறார்.',
      },
    },
    'kunj-bihari-aarti': {
      summary: 'கோகுலாஷ்டமியிலும் கிருஷ்ணன் கோயில்களிலும் பாடப்படும், சோலைகளில் விளையாடும் கிருஷ்ணனின் இந்தி ஆரத்தி. நான்கு பாடல்களில்: ராதையுடன் வைஜயந்தி மாலை, புல்லாங்குழல், குண்டலம் அணிந்த கருநிற வடிவம்; தேவர்கள் தரிசனத்துக்காக ஏங்கும் பொன்மயில் முடி; அவன் திருவடியில் தோன்றி சிவனின் சடையில் தங்கிய கங்கை; கோபர்கள் பாடும், அவன் எளியோரின் முறையீட்டைக் கேட்கும் பிருந்தாவன நிலவொளிக் கரைகள்.',
      verses: {
        '0.0': 'குஞ்சவனத்தில் விளையாடுபவனுக்கு ஆரத்தி; மலையைத் தூக்கிய ஸ்ரீ கிருஷ்ண முராரிக்கு ஆரத்தி.',
        '1.0': 'கழுத்தில் வைஜயந்தி மாலை, இனிய பாலகன் குழல் ஊதுகிறான்; காதுகளில் குண்டலங்கள் மின்னுகின்றன, நந்தனின் மகிழ்ச்சி நந்தலாலா. வானம் போன்ற கருநிற மேனியொளி, தோழி, ராதை அருகில் ஒளிர்கிறாள்; கொடிகளிடையே வனமாலை அணிந்தவன் நிற்கிறான், வண்டு போன்ற சுருள்முடி, நெற்றியில் கஸ்தூரித் திலகம், நிலவு போன்ற ஒளி: இனிய சியாமனுடன் அழகிய தோற்றம், ஸ்ரீ கிரிதர கிருஷ்ண முராரி.',
        '1.1': 'பொன்மயில் முடி ஒளிர்கிறது, தேவர்கள் தரிசனத்துக்கு ஏங்குகின்றனர்; வானிலிருந்து மலர்க்குவியல் பொழிகிறது. முரசங்கு ஒலிக்கிறது, இனிய மிருதங்கம் ஒலிக்கிறது, ஆய்ச்சியர் உடனுள்ளனர்: ஆயர் குலப் பெண்களின் நிகரற்ற அன்பு, ஸ்ரீ கிரிதர கிருஷ்ண முராரிக்கு.',
        '1.2': 'கங்கை எங்கிருந்து தோன்றினாளோ, உள்ளத்தின் துயர் அனைத்தையும் போக்கும் ஸ்ரீ கங்கை, அவளை நினைத்தால் மயக்கம் அகலும்; அவள் சிவனின் தலையில், சடைகளிடையே தங்கி பாவச் சேற்றைக் கழுவுகிறாள்: அத்தகையது ஸ்ரீ வனமாலியின் திருவடி அழகு, ஸ்ரீ கிரிதர கிருஷ்ண முராரியுடையது.',
        '1.3': 'கரையின் ஒளிமிகு மணல் மின்னுகிறது, பிருந்தாவனத்தில் குழல் ஒலிக்கிறது; நாற்புறமும் கோபியர், கோபர், பசுக்கள். மெல்லென, மென்மையாகச் சிரிக்கிறான், நிலவொளி, நிலவு, பிறவிப் பிணைப்புகள் அறுகின்றன: எளியோரின் துயருற்றோரின் முறையீட்டைக் கேள், ஸ்ரீ கிரிதர கிருஷ்ண முராரி.',
      },
    },
  },
};
